import subprocess, os, tempfile, json, sys
cmds=[]
with open('/tmp/help_commands.txt') as f:
    pass
# parse list from captured help stdout
import subprocess as sp
p=sp.run(["/workspace/executable","-quiet","help","commands"], capture_output=True, text=True)
for line in p.stdout.splitlines():
    if line.startswith("    ") and not line.startswith("                         "):
        parts=line.strip().split()
        if parts:
            cmds.append(parts[0])
print(cmds, len(cmds))
results={}
for c in cmds:
    if c=="help": continue
    with tempfile.TemporaryDirectory() as d:
        try:
            pr=sp.run(["/workspace/executable","-quiet",c], capture_output=True, text=True, cwd=d, input="", timeout=5)
            results[c]={"exit":pr.returncode,"out":pr.stdout[:2000],"err":pr.stderr[:4000],"files":os.listdir(d)}
        except sp.TimeoutExpired as e:
            results[c]={"timeout":True,"out":(e.stdout.decode() if isinstance(e.stdout,bytes) else (e.stdout or ""))[:2000] if e.stdout else "","err":(e.stderr.decode() if isinstance(e.stderr,bytes) else (e.stderr or ""))[:4000] if e.stderr else ""}
with open("/tmp/noargs.json","w") as f:
    json.dump(results,f,indent=1)
for c,r in results.items():
    print(c, r.get("exit"), "timeout" if r.get("timeout") else "", "outlen",len(r.get("out","")), "errlen",len(r.get("err","")), "files",r.get("files"))
    # show err tail lines
    err=r.get("err","")
    if err:
        lines=[l for l in err.splitlines() if l.strip()]
        for l in lines[-6:]:
            print("   E:",l[:180])
    out=r.get("out","")
    if out:
        lines=[l for l in out.splitlines() if l.strip()]
        for l in lines[:4]:
            print("   O:",l[:180])
PY
python3 /tmp/probe_noargs.py > /tmp/noargs_summary.txt 2>&1; wc -l /tmp/noargs_summary.txt; head -n 300 /tmp/noargs_summary.txt"}

