import subprocess, os, tempfile, shutil
def run(args, files=None, inp=""):
    with tempfile.TemporaryDirectory() as d:
        if files:
            for n,s in files.items():
                if os.path.exists(s): shutil.copy(s, os.path.join(d,n))
                else: open(os.path.join(d,n),"w").write(s)
        p=subprocess.run(["/workspace/executable","-quiet"]+args, capture_output=True, text=True, cwd=d, input=inp, timeout=5)
        print(args,"exit",p.returncode)
        print("OUT:",p.stdout[:2500])
        print("ERR:",p.stderr[:2500])
        print("FILES",sorted(os.listdir(d)))
        for f in sorted(os.listdir(d)):
            if f not in (files or {}):
                print("---",f); print(open(os.path.join(d,f),errors="ignore").read()[:2000])
run(["analyze","-f","data.xvg"],{"data.xvg":"/tmp/data.xvg"})
run(["analyze","-f","data.xvg","-av"],{"data.xvg":"/tmp/data.xvg"})
run(["sham","-f","data.xvg"],{"data.xvg":"/tmp/data.xvg"})
