# parse options from help
def parse_options(helptext):
    lines=helptext.splitlines()
    try:
        opt_idx=lines.index("OPTIONS")
    except ValueError:
        return []
    opts=[]
    sect="other"
    i=opt_idx+1
    while i < len(lines):
        line=lines[i]
        if line.startswith("Options to specify input files:"):
            sect="input"; i+=1; continue
        if line.startswith("Options to specify output files:"):
            sect="output"; i+=1; continue
        if line.startswith("Options to specify input/output files:"):
            sect="inout"; i+=1; continue
        if line=="Other options:":
            sect="other"; i+=1; continue
        m=re.match(r'^ -(\S+)(?:\s+(.*))?$', line)
        if m:
            token=m.group(1); rest=(m.group(2) or "").strip()
            # description lines following (indent 11)
            desc_lines=[]
            j=i+1
            while j < len(lines) and lines[j].startswith("           "):
                desc_lines.append(lines[j].strip()); j+=1
            desc=" ".join(desc_lines)
            optional=False
            if rest.endswith("(Opt.)"):
                optional=True; rest=rest[:-len("(Opt.)")].strip()
            elif "(Opt.)" in rest:
                # could be in middle? handle
                optional=True; rest=rest.replace("(Opt.)","").strip()
            default=None
            # default is last parenthesized group if rest ends with )
            spec=rest
            if rest.endswith(")"):
                # find matching '(' from end
                depth=0; pos=None
                for k in range(len(rest)-1,-1,-1):
                    if rest[k]==")": depth+=1
                    elif rest[k]=="(":
                        depth-=1
                        if depth==0: pos=k; break
                if pos is not None:
                    default=rest[pos+1:-1]
                    spec=rest[:pos].strip()
            is_bool=False; name=token
            if token.startswith("[no]"):
                is_bool=True; name=token[4:]
            kind="bool" if is_bool else None
            multi=False
            if not is_bool:
                s=spec
                if s.startswith("[<") or s.startswith("<.") or (s.startswith("[<") ):
                    kind="file"; multi="[...]" in s
                elif "<dir>" in s:
                    kind="dir"; multi="[...]" in s
                elif s=="<enum>": kind="enum"
                elif s=="<int>": kind="int"
                elif s=="<real>": kind="real"
                elif s=="<time>": kind="time"
                elif s=="<string>": kind="string"
                elif s=="<vector>": kind="vector"
                elif s=="<selection>": kind="selection"
                elif s=="<file>": kind="selfile"
                elif s.startswith("[<"): kind="file"; multi="[...]" in s
                elif s=="":
                    kind="bool"; is_bool=True  # shouldn't happen
                else:
                    kind="unknown:"+s
            opts.append({"name":name,"bool":is_bool,"kind":kind,"spec":spec,"default":default,"opt":optional,"sect":sect,"desc":desc})
            i=j; continue
        i+=1
    return opts

