# Probing functions
def extract_allowed(err):
    # Allowed values: a, b, c.
    m=re.search(r'Allowed values: (.+)', err)
    if m:
        txt=m.group(1).strip()
        # values line may be wrapped? In error block values are on one line? Check - it's single line up to period? values may contain ?
        # The error message ends with '.' ; strip trailing .
        if txt.endswith("."): txt=txt[:-1]
        return [x.strip() for x in txt.split(",")]
    return None

def probe_enum(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","__bogus_enum__"], timeout=5)
        vals=extract_allowed(pr.stderr)
        if vals: return (c,opt['name'],vals)
        # fallback parse desc for colon list
        return (c,opt['name'],None)
    except Exception as e:
        return (c,opt['name'],None)

def probe_int(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","2147483648"], timeout=5)
        if "integer overflow" in pr.stderr:
            return (c,opt['name'],32)
        else:
            return (c,opt['name'],64)
    except Exception as e:
        return (c,opt['name'],32)

def probe_real(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","1e100"], timeout=5)
        if "overflow/underflow" in pr.stderr:
            return (c,opt['name'],"float")
        else:
            return (c,opt['name'],"double")
    except Exception as e:
        return (c,opt['name'],"float")

def probe_selection(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","all","all"], timeout=5)
        if "Too many values" in pr.stderr:
            return (c,opt['name'],False)
        else:
            return (c,opt['name'],True)
    except Exception as e:
        return (c,opt['name'],False)

def probe_file(cmd_opt):
