def probe_enum(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","__bogus_enum__"], timeout=5)
        vals=extract_allowed(pr.stderr)
        if vals: return (c,opt['name'],vals)
        # fallback parse desc for colon list
        return (c,opt['name'],None)
    except Exception as e:
        return (c,opt['name'],None)

def probe_int(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","2147483648"], timeout=5)
        if "integer overflow" in pr.stderr:
            return (c,opt['name'],32)
        else:
            return (c,opt['name'],64)
    except Exception as e:
        return (c,opt['name'],32)

def probe_real(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","1e100"], timeout=5)
        if "overflow/underflow" in pr.stderr:
            return (c,opt['name'],"float")
        else:
            return (c,opt['name'],"double")
    except Exception as e:
        return (c,opt['name'],"float")

def probe_selection(cmd_opt):
    c,opt=cmd_opt
    try:
        pr=runq([c,f"-{opt['name']}","all","all"], timeout=5)
        if "Too many values" in pr.stderr:
            return (c,opt['name'],False)
        else:
            return (c,opt['name'],True)
    except Exception as e:
        return (c,opt['name'],False)

def probe_file(cmd_opt):
    c,opt=cmd_opt
    # extensions with missing file
    exts=None; allow=False
    try:
        with tempfile.TemporaryDirectory() as d:
            pr=runq([c,f"-{opt['name']}","zzmissingprobe"], cwd=d, timeout=5)
            err=pr.stderr
            # extract extensions list line after "extensions were tried" or "extensions are possible" or "Only the following"
            m=re.search(r'The following extensions[^\n]*\n\s+([^\n]+)', err)
            if not m:
                m=re.search(r'Only the following extensions are possible:\n\s+([^\n]+)', err)
            if not m:
                m=re.search(r'The following extensions are possible for this option:\n\s+([^\n]+)', err)
            if m:
                exts=[x.strip() for x in m.group(1).split(",")]
            # allowUnknown
            with open(os.path.join(d,"zzprobe.txt"),"w") as f: f.write("hi\n")
            pr2=runq([c,f"-{opt['name']}","zzprobe.txt"], cwd=d, timeout=5)
            err2=pr2.stderr
            if "cannot be used" in err2:
                allow=False
            elif f"In command-line option -{opt['name']}" in err2 and "Invalid command-line options" in err2:
                # if other parse rejection like file name cannot...
                if "File name" in err2 or "File '" in err2:
                    # Could be ??? check specifics
                    allow=False if "cannot be used" in err2 else True
                else:
                    allow=True
            else:
                allow=True
    except subprocess.TimeoutExpired:
        allow=True
    except Exception as e:
        pass
    return (c,opt['name'],exts,allow)

