package main

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"io"
)

//go:embed data.json.gz
var compressedData []byte

type OptionDef struct {
	Name         string   `json:"name"`
	Bool         bool     `json:"bool"`
	Kind         string   `json:"kind"`
	Spec         string   `json:"spec"`
	Default      *string  `json:"default"`
	Opt          bool     `json:"opt"`
	Sect         string   `json:"sect"`
	Desc         string   `json:"desc"`
	Allowed      []string `json:"allowed"`
	Bits         int      `json:"bits"`
	Prec         string   `json:"prec"`
	Multi        bool     `json:"multi"`
	Exts         []string `json:"exts"`
	AllowUnknown *bool    `json:"allowUnknown"`
	AllowMissing bool     `json:"allowMissing"`
	// runtime additions
	IsCommon bool `json:"-"`
}

type NoArgs struct {
	Exit  int    `json:"exit"`
	Out   string `json:"out"`
	Err   string `json:"err"`
	Files []string `json:"files"`
}

type Data struct {
	Commands    []string              `json:"commands"`
	Descs       map[string]string     `json:"descs"`
	Helps       map[string]string     `json:"helps"`
	Options     map[string][]OptionDef `json:"options"`
	Topics      map[string]string     `json:"topics"`
	Subtopics   map[string]string     `json:"subtopics"`
	RootHelp    string                `json:"root_help"`
	VersionBody string                `json:"version_body"`
	Copyright   string                `json:"copyright"`
	NoArgs      map[string]NoArgs     `json:"noargs"`
	Quotes      []string              `json:"quotes"`
}

var data Data
var commandSet map[string]bool
var recognizedExts map[string]bool

func loadData() {
	r, err := gzip.NewReader(bytes.NewReader(compressedData))
	if err != nil { panic(err) }
	b, err := io.ReadAll(r)
	if err != nil { panic(err) }
	if err := json.Unmarshal(b, &data); err != nil { panic(fmt.Sprintf("data decode: %v", err)) }
	commandSet = map[string]bool{}
	for _, c := range data.Commands { commandSet[c]=true }
	recognizedExts = map[string]bool{}
	for _, opts := range data.Options {
		for _, o := range opts {
			for _, e := range o.Exts { recognizedExts[e]=true }
		}
	}
	// extra extensions that GROMACS recognises as file types but may not
	// appear as an input/output option extension list
	for _, e := range []string{".txt",".mdp",".top",".gro",".pdb",".ndx",".xvg",".edr",".tpr",".trr",".xtc",".cpt",".log",".mtx",".tex",".xpm",".eps",".dat",".edi",".inp",".rtp",".itp",".m2p",".pqr",".csv",".esp",".brk",".ent",".g96",".h5md",".tng",".out"} {
		_ = e // intentionally not marking .txt etc as recognised; see validateFile
	}
}
GO
