{"command":"cat > /workspace/errors.go << 'GO'
package main

import (
	"fmt"
	"strings"
)

type ErrorBlock struct {
	Program string // display e.g. "gmx check" or progBase
	Source  string // e.g. src/gromacs/commandline/cmdlineparser.cpp
	Line    int
	Func    string // may be empty
	Heading string // e.g. "Error in user input:"
	Body    string // text after heading, without trailing blank line
}

func (e *ErrorBlock) String() string {
	var b strings.Builder
	b.WriteString("\n-------------------------------------------------------\n")
	b.WriteString(fmt.Sprintf("Program:     %s, version %s\n", e.Program, versionStr))
	b.WriteString(fmt.Sprintf("Source file: %s (line %d)\n", e.Source, e.Line))
	if e.Func != "" {
		b.WriteString(fmt.Sprintf("Function:    %s\n", e.Func))
	}
	b.WriteString("\n")
	b.WriteString(e.Heading + "\n")
	b.WriteString(e.Body)
	if !strings.HasSuffix(e.Body, "\n") { b.WriteString("\n") }
	b.WriteString("\nFor more information and tips for troubleshooting, please check the GROMACS\n")
	b.WriteString("website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n")
	b.WriteString("-------------------------------------------------------\n")
	return b.String()
}

func parserErrorBlock(program string, lines []string) *ErrorBlock {
	return &ErrorBlock{
		Program: program,
		Source: "src/gromacs/commandline/cmdlineparser.cpp", Line: 271,
		Func: "void gmx::CommandLineParser::parse(int*, char**)",
		Heading: "Error in user input:",
		Body: "Invalid command-line options\n" + strings.Join(lines, "\n") + "\n",
	}
}
func positionalErrorBlock(program string, arg string) *ErrorBlock {
	msg := fmt.Sprintf("Positional argument '%s' cannot be accepted. Perhaps you forgot to put a hyphen before an option name.", arg)
	wrapped := wrapText(msg, "", 78)
	return &ErrorBlock{
		Program: program,
		Source: "src/gromacs/commandline/cmdlineparser.cpp", Line: 167,
		Func: "void gmx::CommandLineParser::parse(int*, char**)",
		Heading: "Error in user input:",
		Body: strings.Join(wrapped, "\n") + "\n",
	}
}
func unknownCommandErrorBlock(program string, cmd string) *ErrorBlock {
	msg := fmt.Sprintf("'%s' is not a GROMACS command.", cmd)
	wrapped := wrapText(msg, "", 78)
	return &ErrorBlock{
		Program: program,
		Source: "src/gromacs/commandline/cmdlinemodulemanager.cpp", Line: 389,
		Func: "gmx::ICommandLineModule* gmx::CommandLineModuleManager::Impl::processCommonOptions(gmx::CommandLineCommonOptionsHolder*, int*, char***)",
		Heading: "Error in user input:",
		Body: strings.Join(wrapped, "\n") + "\n",
	}
}
func optionsFinishErrorBlock(program string, entries []string) *ErrorBlock {
	body := "Invalid input values\n" + strings.Join(entries, "\n") + "\n"
	return &ErrorBlock{
		Program: program,
		Source: "src/gromacs/options/options.cpp", Line: 184,
		Func: "void gmx::internal::OptionSectionImpl::finish()",
		Heading: "Error in user input:",
		Body: body,
	}
}
GO
"}

