var numericPattern = regexp.MustCompile(`^[+-]?((([0-9]+(\.[0-9]*)?)|(\.[0-9]+))([eE][+-]?[0-9]+)?|0[xX](([0-9a-fA-F]+(\.[0-9a-fA-F]*)?)|(\.[0-9a-fA-F]+))([pP][+-]?[0-9]+)?|inf(inity)?|nan)$`)
var decimalPattern = regexp.MustCompile(`^[+-]?(([0-9]+(\.[0-9]*)?)|(\.[0-9]+))([eE][+-]?[0-9]+)?$`)
var hexPattern = regexp.MustCompile(`^[+-]?0[xX](([0-9a-fA-F]+(\.[0-9a-fA-F]*)?)|(\.[0-9a-fA-F]+))([pP][+-]?[0-9]+)?$`)
