	if low == "inf" || low == "+inf" || low == "-inf" || low == "infinity" || low == "+infinity" || low == "-infinity" {
		return 0, 2
	}
	isHex := hexPattern.MatchString(s)
	isDec := decimalPattern.MatchString(s)
	isNan := low == "nan" || low == "+nan" || low == "-nan"
	if !isHex && !isDec && !isNan {
		return 0, 1
	}
	var val float64
	var err error
	if isNan {
