	// GROMACS std::stod throws for results that are subnormal in double: smallest normal is 2.2250738585072014e-308
	if val != 0 && !isNanVal(val) {
		av := val; if av < 0 { av = -av }
		if av < 2.2250738585072014e-308 {
			return 0, 2
		}
	}
	if prec == "float" {
		f := float32(val)
		if isInfFloat(float64(f)) && !isInfFloat(val) {
			return 0, 2
		}
		val = float64(f)
	}
	return val, 0
}
func nanValue() float64 { return strconv.NaN() }
func isNanVal(v float64) bool { return v != v }
func isInfFloat(v float64) bool { return v > 1.7976931348623157e308 || v < -1.7976931348623157e308 }

func parseHexFloat(s string) (float64, error) {
	// handle optional p exponent
	neg := false
	if strings.HasPrefix(s, "+") { s=s[1:] } else if strings.HasPrefix(s, "-") { neg=true; s=s[1:] }
	s = s[2:] // 0x
	exp := 0
	if idx := strings.IndexAny(s, "pP"); idx >= 0 {
		e, err := strconv.Atoi(s[idx+1:]); if err != nil { return 0, err }
		exp = e; s = s[:idx]
	}
	intPart := s; fracPart := ""
	if idx := strings.Index(s, "."); idx>=0 { intPart=s[:idx]; fracPart=s[idx+1:] }
	var val float64=0
	for _,c := range intPart {
		d,err:=strconv.ParseInt(string(c),16,32); if err!=nil {return 0,err}; val=val*16+float64(d)
	}
	place:=1.0/16
	for _,c := range fracPart {
		d,err:=strconv.ParseInt(string(c),16,32); if err!=nil {return 0,err}; val+=float64(d)*place; place/=16
	}
	// apply 2^exp
	for exp>0 { val*=2; exp-- }
	for exp<0 { val/=2; exp++ }
	if neg { val=-val }
	return val, nil
}

func parseIntStr(v string, bits int) (int64, int) {
	s := strings.TrimLeft(v, " \t\n\v\f\r")
	if !intPattern.MatchString(s) { return 0,1 }
	val, err := strconv.ParseInt(s, 10, bits)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange { return 0,2 }
		return 0,1
	}
	return val,0
}

func fileExtOf(v string) string {
	base := v
	if idx:=strings.LastIndex(base,"/"); idx>=0 { base=base[idx+1:] }
	idx:=strings.LastIndex(base,".")
	if idx<0 { return "" }
	return base[idx:]
}

func joinExts(exts []string) string { return strings.Join(exts, ", ") }

func extractErrno(err error) syscall.Errno {
	if err == nil { return 0 }
	if pe, ok := err.(*os.PathError); ok {
		if en, ok2 := pe.Err.(syscall.Errno); ok2 { return en }
	}
	if en, ok := err.(syscall.Errno); ok { return en }
	return syscall.EIO
}

// validateFileValue returns resolved name and error lines (without option header)
func validateFileValue(def OptionDef, v string) (string, []string) {
	ext := fileExtOf(v)
	exts := def.Exts
	if def.Sect == "output" {
		if ext != "" && recognizedExts[ext] {
			found:=false; for _,e:=range exts { if e==ext {found=true} }
			if !found {
				lines:=wrapText(fmt.Sprintf("File name '%s' cannot be used for this option.", v), "    ", 78)
				lines=append(lines, "    Only the following extensions are possible:", "      "+joinExts(exts))
				return v, lines
			}
			return v, nil
		}
		// append default extension
		if len(exts)>0 { return v+exts[0], nil }
		return v, nil
	}
	// input / inout
	if ext != "" && recognizedExts[ext] {
		found:=false; for _,e:=range exts { if e==ext {found=true} }
		if !found {
			lines:=wrapText(fmt.Sprintf("File name '%s' cannot be used for this option.", v), "    ", 78)
			lines=append(lines, "    Only the following extensions are possible:", "      "+joinExts(exts))
			return v, lines
		}
		// allowed extension: check existence
		fi, err := os.Stat(v)
		if err != nil {
			en:=extractErrno(err); reason,code:=errnoString(en)
			lines:=wrapText(fmt.Sprintf("File '%s' does not exist or is not accessible.", v), "    ", 78)
			lines=append(lines, "    The file could not be opened.", fmt.Sprintf("      Reason: %s", reason), fmt.Sprintf("      (call to fopen() returned error code %d)", code))
			return v, lines
		}
		if !fi.Mode().IsRegular() {
			lines:=wrapText(fmt.Sprintf("Failed to access file '%s'.", v), "    ", 78)
			lines=append(lines, "    The file is not a regular file.")
			return v, lines
		}
		f, err := os.Open(v)
		if err != nil {
			en:=extractErrno(err); reason,code:=errnoString(en)
			lines:=wrapText(fmt.Sprintf("Failed to access file '%s'.", v), "    ", 78)
			lines=append(lines, "    The file could not be opened.", fmt.Sprintf("      Reason: %s", reason), fmt.Sprintf("      (call to fopen() returned error code %d)", code))
			return v, lines
		}
		f.Close()
		return v, nil
	}
	// unrecognised or no extension: try completion
	for _, e := range exts {
		cand:=v+e
		if fi, err:=os.Stat(cand); err==nil && fi.Mode().IsRegular() {
			if f, err:=os.Open(cand); err==nil { f.Close(); return cand, nil }
		}
	}
	if fi, err:=os.Stat(v); err==nil {
		allow := def.AllowUnknown != nil && *def.AllowUnknown
		if !fi.Mode().IsRegular() {
			lines:=wrapText(fmt.Sprintf("Failed to access file '%s'.", v), "    ", 78)
			lines=append(lines, "    The file is not a regular file.")
			return v, lines
		}
		if allow {
			if f, err:=os.Open(v); err!=nil {
				en:=extractErrno(err); reason,code:=errnoString(en)
				lines:=wrapText(fmt.Sprintf("Failed to access file '%s'.", v), "    ", 78)
				lines=append(lines, "    The file could not be opened.", fmt.Sprintf("      Reason: %s", reason), fmt.Sprintf("      (call to fopen() returned error code %d)", code))
				return v, lines
			} else { f.Close() }
			return v, nil
		}
		lines:=wrapText(fmt.Sprintf("File '%s' cannot be used by GROMACS because it does not have a recognizable extension.", v), "    ", 78)
		lines=append(lines, "    The following extensions are possible for this option:", "      "+joinExts(exts))
		return v, lines
	}
	if def.AllowMissing {
		return v, nil
	}
	lines:=wrapText(fmt.Sprintf("File '%s' does not exist or is not accessible.", v), "    ", 78)
	lines=append(lines, "    The following extensions were tried to complete the file name:", "      "+joinExts(exts))
	return v, lines
}

func validateSelFileValue(v string) []string {
	fi, err:=os.Stat(v)
	if err!=nil {
		en:=extractErrno(err); reason,code:=errnoString(en)
		lines:=[]string{fmt.Sprintf("    Error in parsing selections from file '%s'", v), fmt.Sprintf("      Could not open file '%s'", v), fmt.Sprintf("        Reason: %s", reason), fmt.Sprintf("        (call to fopen() returned error code %d)", code)}
		return lines
	}
	if !fi.Mode().IsRegular() {
		lines:=[]string{fmt.Sprintf("    Error in parsing selections from file '%s'", v), fmt.Sprintf("      Could not open file '%s'", v), "        Reason: Is a directory", "        (call to fopen() returned error code 21)"}
		return lines
	}
	if f,err:=os.Open(v); err!=nil {
		en:=extractErrno(err); reason,code:=errnoString(en)
		return []string{fmt.Sprintf("    Error in parsing selections from file '%s'", v), fmt.Sprintf("      Could not open file '%s'", v), fmt.Sprintf("        Reason: %s", reason), fmt.Sprintf("        (call to fopen() returned error code %d)", code)}
	} else { f.Close() }
	return nil
}

func optErrorLines(display string, msgLines []string) []string {
	lines:=[]string{"  In command-line option "+display}
	lines=append(lines, msgLines...)
	return lines
}
func msgInvalidValue(display string, v string, suffix string) []string {
	msg:=fmt.Sprintf("Invalid value: '%s'; %s", v, suffix)
	return optErrorLines(display, wrapText(msg, "    ", 78))
}

func parseArgs(args []string, defs []OptionDef, allowPositional bool) *ParseResult {
	res:=&ParseResult{Options:map[string]*ParsedOption{}, BoolVals:map[string]bool{}}
	defMap:=map[string]OptionDef{}
	for _,d:=range defs { defMap[d.Name]=d }
	seen:=map[string]bool{}
	addErr:=func(lines []string, isCommon bool){ res.Errors=append(res.Errors, ParseError{Lines:lines, IsCommon:isCommon}) }
	i:=0
	for i<len(args) {
		tok:=args[i]
		if !isOptionLike(tok) {
			// positional
			if allowPositional {
				res.Positionals=append(res.Positionals, tok)
			} else {
				if !res.HasPositional { res.HasPositional=true; res.FirstPositional=tok }
			}
			i++; continue
		}
		// option token
		var name string
		if strings.HasPrefix(tok, "--") && len(tok)>2 { name=tok[2:] } else { name=tok[1:] }
		def, ok:=defMap[name]
		noPrefix:=false
		if !ok && strings.HasPrefix(name, "no") {
			if d2, ok2:=defMap[name[2:]]; ok2 && d2.Bool { def=d2; ok=true; noPrefix=true }
		}
		// collect values
		j:=i+1; var values []string
		for j<len(args) && !isOptionLike(args[j]) { values=append(values, args[j]); j++ }
		if !ok {
			lines:=wrapText(fmt.Sprintf("Unknown command-line option %s", tok), "    ", 78)
			addErr(lines, false)
			i=j; continue
		}
		if seen[def.Name] {
			addErr(optErrorLines(tok, []string{"    Option specified multiple times"}), def.IsCommon)
			i=j; continue
		}
		seen[def.Name]=true
		po:=&ParsedOption{Def:def, Display:tok, Values:values, Set:true}
		res.Options[def.Name]=po
		// validate
		if def.Bool {
			if len(values)==0 {
				po.BoolVal=!noPrefix
				if def.IsCommon { res.BoolVals[def.Name]=po.BoolVal }
			} else {
				// validate each
				for idx,v:=range values {
					b, valid:=parseBoolStr(v)
					if idx==0 {
						if valid {
							if noPrefix { po.BoolVal=false } else { po.BoolVal=b }
							if def.IsCommon && !noPrefix { res.BoolVals[def.Name]=po.BoolVal }
							if def.IsCommon && noPrefix { res.BoolVals[def.Name]=false }
						} else {
							msg:=fmt.Sprintf("Invalid value: '%s'; supported values are: 1, 0, yes, no, true, false", v)
							addErr(optErrorLines(tok, wrapText(msg, "    ",78)), def.IsCommon)
						}
					} else {
						if valid {
							addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon)
						} else {
							msg:=fmt.Sprintf("Invalid value: '%s'; supported values are: 1, 0, yes, no, true, false", v)
							addErr(optErrorLines(tok, wrapText(msg, "    ",78)), def.IsCommon)
						}
					}
				}
				if noPrefix {
					addErr(optErrorLines(tok, []string{"    Cannot specify a value together with 'no' prefix"}), def.IsCommon)
				}
			}
			i=j; continue
		}
		// non-bool
		kind:=def.Kind
		if len(values)==0 {
			switch kind {
			case "file":
				if !strings.HasPrefix(def.Spec, "[") {
					addErr(optErrorLines(tok, []string{"    Too few (valid) values"}), def.IsCommon)
				}
			case "selfile":
				addErr(optErrorLines(tok, []string{"    No file name provided"}), def.IsCommon)
			case "dir", "selection":
				// OK empty
			default:
				addErr(optErrorLines(tok, []string{"    Too few (valid) values"}), def.IsCommon)
			}
			i=j; continue
		}
		// have values
		if kind=="vector" {
			anyInvalid:=false
			for _,v:=range values {
				_, st:=parseRealStr(v, "float")
				if st!=0 {
					anyInvalid=true
					if st==2 { addErr(msgInvalidValue(tok, v, "it causes an overflow/underflow"), def.IsCommon) } else { addErr(msgInvalidValue(tok, v, "expected a number"), def.IsCommon) }
				} else {
					po.Resolved=append(po.Resolved, v)
				}
			}
			if !anyInvalid {
				if len(values)==2 {
					addErr(optErrorLines(tok, []string{"    Expected 1 or 3 values, got 2"}), def.IsCommon)
				} else if len(values)>3 {
					for k:=3;k<len(values);k++ { addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon) }
				}
			}
			i=j; continue
		}
		// max count
		maxCount:=1
		if def.Multi { maxCount=1<<30 }
		for idx,v:=range values {
			if idx < maxCount {
				switch kind {
				case "int":
					bits:=def.Bits; if bits==0 {bits=32}
					_, st:=parseIntStr(v,bits)
					if st==1 { addErr(msgInvalidValue(tok, v, "expected an integer"), def.IsCommon) } else if st==2 { addErr(msgInvalidValue(tok, v, "it causes an integer overflow"), def.IsCommon) } else { po.Resolved=append(po.Resolved,v) }
				case "real", "time":
					prec:=def.Prec; if prec=="" {prec="float"}
					_, st:=parseRealStr(v, prec)
					if st==1 { addErr(msgInvalidValue(tok, v, "expected a number"), def.IsCommon) } else if st==2 { addErr(msgInvalidValue(tok, v, "it causes an overflow/underflow"), def.IsCommon) } else { po.Resolved=append(po.Resolved,v) }
				case "enum":
					found:=false; for _,a:=range def.Allowed { if a==v {found=true} }
					if !found {
						msg:=fmt.Sprintf("Invalid value: %s. Allowed values: %s.", v, strings.Join(def.Allowed, ", "))
						addErr(optErrorLines(tok, wrapText(msg, "    ",78)), def.IsCommon)
					} else { po.Resolved=append(po.Resolved,v) }
				case "file":
					resolved, lines:=validateFileValue(def, v)
					if lines!=nil { addErr(optErrorLines(tok, lines), def.IsCommon) } else { po.Resolved=append(po.Resolved, resolved) }
				case "selfile":
					lines:=validateSelFileValue(v)
					if lines!=nil { addErr(optErrorLines(tok, lines), def.IsCommon) } else { po.Resolved=append(po.Resolved,v) }
				case "selection", "string", "dir":
					po.Resolved=append(po.Resolved, v)
				default:
					po.Resolved=append(po.Resolved, v)
				}
			} else {
				// excess: validate validity; if valid -> Too many, else specific error
				switch kind {
				case "int":
					bits:=def.Bits; if bits==0 {bits=32}
					_, st:=parseIntStr(v,bits)
					if st==1 { addErr(msgInvalidValue(tok, v, "expected an integer"), def.IsCommon) } else if st==2 { addErr(msgInvalidValue(tok, v, "it causes an integer overflow"), def.IsCommon) } else { addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon) }
				case "real", "time":
					prec:=def.Prec; if prec=="" {prec="float"}
					_, st:=parseRealStr(v, prec)
					if st==1 { addErr(msgInvalidValue(tok, v, "expected a number"), def.IsCommon) } else if st==2 { addErr(msgInvalidValue(tok, v, "it causes an overflow/underflow"), def.IsCommon) } else { addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon) }
				case "enum":
					found:=false; for _,a:=range def.Allowed { if a==v {found=true} }
					if !found {
						msg:=fmt.Sprintf("Invalid value: %s. Allowed values: %s.", v, strings.Join(def.Allowed, ", "))
						addErr(optErrorLines(tok, wrapText(msg, "    ",78)), def.IsCommon)
					} else { addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon) }
				case "file":
					_, lines:=validateFileValue(def, v)
					if lines!=nil { addErr(optErrorLines(tok, lines), def.IsCommon) } else { addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon) }
				case "selfile":
					lines:=validateSelFileValue(v)
					if lines!=nil { addErr(optErrorLines(tok, lines), def.IsCommon) } else { addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon) }
				default:
					addErr(optErrorLines(tok, []string{"    Too many values"}), def.IsCommon)
				}
			}
		}
		i=j
	}
	return res
}

// error selection helpers
func (r *ParseResult) commonErrors() []ParseError {
	var out []ParseError
	for _,e:=range r.Errors { if e.IsCommon { out=append(out,e) } }
	return out
}
func (r *ParseResult) otherErrors() []ParseError {
	// all errors (used when no common)
	return r.Errors
}
GO
"}

