func run(args []string) int {
	common := commonOptionDefs()
	// find candidate: first token not starting with '-'
	candIdx := -1
	cand := ""
	for i, a := range args {
		if !strings.HasPrefix(a, "-") { candIdx = i; cand = a; break }
	}
	if candIdx == -1 {
		// root parse
		res := parseArgs(args, common, false)
		quiet := res.BoolVals["quiet"]
		if len(res.Errors) > 0 || res.HasPositional {
			if !quiet { fmt.Fprint(os.Stderr, startupText(progBase, false)) }
			fmt.Fprint(os.Stderr, selectErrorBlock(res, progBase).String())
			return 1
		}
		if res.BoolVals["version"] {
			fmt.Fprint(os.Stdout, versionOutput(progBase, res.BoolVals["copyright"], quiet))
			return 0
		}
		if !quiet { fmt.Fprint(os.Stderr, startupText(progBase, res.BoolVals["copyright"])) }
		fmt.Fprint(os.Stdout, data.RootHelp)
		if !quiet { fmt.Fprint(os.Stderr, finalLine()) }
		return 0
	}
	// prefix parse
	prefixArgs := args[:candIdx]
	pres := parseArgs(prefixArgs, common, false)
	pquiet := pres.BoolVals["quiet"]
	if len(pres.Errors) > 0 || pres.HasPositional {
		if !pquiet { fmt.Fprint(os.Stderr, startupText(progBase, false)) }
		fmt.Fprint(os.Stderr, selectErrorBlock(pres, progBase).String())
		return 1
	}
	if pres.BoolVals["version"] {
		fmt.Fprint(os.Stdout, versionOutput(progBase, pres.BoolVals["copyright"], pquiet))
		return 0
	}
	if pres.BoolVals["h"] {
		if !pquiet { fmt.Fprint(os.Stderr, startupText(progBase, pres.BoolVals["copyright"])) }
		fmt.Fprint(os.Stdout, data.RootHelp)
		if !pquiet { fmt.Fprint(os.Stderr, finalLine()) }
		return 0
	}
	if !commandSet[cand] {
		if !pquiet { fmt.Fprint(os.Stderr, startupText(progBase, false)) }
		fmt.Fprint(os.Stderr, unknownCommandErrorBlock(progBase, cand).String())
		return 1
	}
	// dispatch module
	display := "gmx " + cand
	var moduleArgs []string
	moduleArgs = append(moduleArgs, args[:candIdx]...)
	moduleArgs = append(moduleArgs, args[candIdx+1:]...)
	var defs []OptionDef
	defs = append(defs, common...)
	if cand != "help" {
		defs = append(defs, data.Options[cand]...)
	}
	res := parseArgs(moduleArgs, defs, cand == "help")
	quiet := res.BoolVals["quiet"]
	copyright := res.BoolVals["copyright"]
	if ce := res.commonErrors(); len(ce) > 0 {
		if !quiet { fmt.Fprint(os.Stderr, startupText(display, copyright)) }
		fmt.Fprint(os.Stderr, parserErrorBlock(display, flattenErrors(ce)).String())
		return 1
	}
	if res.BoolVals["version"] {
		fmt.Fprint(os.Stdout, versionOutput(display, copyright, quiet))
		return 0
	}
	if res.BoolVals["h"] {
		if !quiet { fmt.Fprint(os.Stderr, startupText(display, copyright)) }
		if cand == "help" {
			fmt.Fprint(os.Stdout, "Usage: gmx help [<command>|<topic> [<subtopic> [...]]]\n")
		} else {
			fmt.Fprint(os.Stdout, data.Helps[cand])
		}
		if !quiet { fmt.Fprint(os.Stderr, finalLine()) }
		return 0
	}
	if res.HasPositional {
		if !quiet { fmt.Fprint(os.Stderr, startupText(display, copyright)) }
		fmt.Fprint(os.Stderr, positionalErrorBlock(display, res.FirstPositional).String())
		return 1
	}
	if len(res.Errors) > 0 {
		if !quiet { fmt.Fprint(os.Stderr, startupText(display, copyright)) }
		fmt.Fprint(os.Stderr, parserErrorBlock(display, flattenErrors(res.Errors)).String())
		return 1
	}
	// execute
	if !quiet { fmt.Fprint(os.Stderr, startupText(display, copyright)) }
	result := executeModule(cand, res, display)
	if result.Out != "" { fmt.Fprint(os.Stdout, result.Out) }
	if result.ErrExtra != "" { fmt.Fprint(os.Stderr, result.ErrExtra) }
	if result.Block != nil {
		fmt.Fprint(os.Stderr, result.Block.String())
		if result.Exit == 0 { return 1 }
		return result.Exit
	}
	if result.SuppressFinal {
		return result.Exit
	}
	if !quiet { fmt.Fprint(os.Stderr, finalLine()) }
	return result.Exit
}
