package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

type ExecResult struct {
	Out string
	ErrExtra string
	Exit int
	Block *ErrorBlock
	SuppressFinal bool
	Backup bool // whether common backup option applies (handled in helpers)
}

func (r *ParseResult) get(name string) *ParsedOption {
	if p, ok := r.Options[name]; ok { return p }
	return nil
}
func (r *ParseResult) isSet(name string) bool {
	_, ok := r.Options[name]; return ok
}
func (r *ParseResult) values(name string) []string {
	if p := r.get(name); p != nil { return p.Values }
	return nil
}
func (r *ParseResult) resolved(name string) []string {
	if p := r.get(name); p != nil {
		if len(p.Resolved)>0 { return p.Resolved }
		return p.Values
	}
	return nil
}
func (r *ParseResult) resolvedOrDefault(name string) string {
	// for handlers: first resolved value or default
	if p := r.get(name); p != nil && len(p.Values)>0 {
		res := r.resolved(name); if len(res)>0 { return res[0] }
	}
	// find def default
	// caller knows def; this helper searches global? not available; return ""
	return ""
}
func (r *ParseResult) boolVal(name string, deflt bool) bool {
	if p := r.get(name); p != nil { return p.BoolVal }
	return deflt
}
func (r *ParseResult) backupEnabled() bool {
	if p := r.get("backup"); p != nil { return p.BoolVal }
	return true
}

func defaultFileBase(def OptionDef) string {
	d := ""
	if def.Default != nil { d = *def.Default }
	if idx := strings.LastIndex(d, "."); idx >= 0 { return d[:idx] }
	return d
}
func fileExistsWithCompletion(def OptionDef) (string, bool) {
	if def.Default == nil { return "", false }
	d := *def.Default
	if fi, err := os.Stat(d); err == nil && fi.Mode().IsRegular() { return d, true }
	base := defaultFileBase(def)
	for _, e := range def.Exts {
		cand := base + e
		if fi, err := os.Stat(cand); err == nil && fi.Mode().IsRegular() { return cand, true }
	}
	return "", false
}

func requiredFileErrors(cmd string, res *ParseResult) []string {
	defs := data.Options[cmd]
	var req []OptionDef
	for _, d := range defs {
		if d.Kind == "file" && d.Sect == "input" && !d.Opt {
			req = append(req, d)
		}
	}
	sort.Slice(req, func(i,j int) bool { return req[i].Name < req[j].Name })
	var entries []string
	for _, d := range req {
		base := defaultFileBase(d)
		p := res.get(d.Name)
		if p != nil && len(p.Values) > 0 {
			continue
		}
		if _, ok := fileExistsWithCompletion(d); ok { continue }
		var phrase string
		if p != nil {
			phrase = fmt.Sprintf("No file name was provided, and the default file '%s' does not exist or is not accessible.", base)
		} else {
			phrase = fmt.Sprintf("Required option was not provided, and the default file '%s' does not exist or is not accessible.", base)
		}
		lines := []string{"  In option " + d.Name}
		lines = append(lines, wrapText(phrase, "    ", 78)...)
		lines = append(lines, "    The following extensions were tried to complete the file name:", "      "+joinExts(d.Exts))
		entries = append(entries, strings.Join(lines, "\n"))
	}
	return entries
}

func hasModuleOptions(cmd string, res *ParseResult) bool {
	for name := range res.Options {
		isCommon := false
		for _, c := range commonOptionDefs() { if c.Name==name { isCommon=true } }
		if !isCommon { return true }
	}
	return false
}

func executeModule(cmd string, res *ParseResult, display string) ExecResult {
	if cmd == "help" {
		return executeHelp(res)
	}
	// specialised handlers that manage their own option-finished logic
	switch cmd {
	case "sigeps":
		return handleSigeps(res, display)
	}
	// generic required-file check
	if entries := requiredFileErrors(cmd, res); len(entries)>0 {
		return ExecResult{Block: optionsFinishErrorBlock(display, entries), Exit: 1}
	}
	switch cmd {
	case "check":
		return handleCheck(res, display)
	case "dump":
		return handleDump(res, display)
	case "analyze":
		if r:=handleAnalyze(res, display); r != nil { return *r }
	}
	// stored no-argument behaviour as fallback
	if na, ok := data.NoArgs[cmd]; ok {
		suppress := na.Exit != 0
		return ExecResult{Out: na.Out, ErrExtra: na.Err, Exit: na.Exit, SuppressFinal: suppress}
	}
	return ExecResult{Exit: 0}
}

func executeHelp(res *ParseResult) ExecResult {
	topics := res.Positionals
	if len(topics)==0 {
		return ExecResult{Out: data.RootHelp, Exit:0}
	}
	first := topics[0]
	isCmd := commandSet[first]
	if first!="commands" && first!="selections" && first!="help" && !isCmd {
		return ExecResult{ErrExtra: fmt.Sprintf("No help available for '%s'\n", first), Exit:2}
	}
	if len(topics)==1 {
		switch first {
		case "commands": return ExecResult{Out: data.Topics["commands"]}
		case "selections": return ExecResult{Out: data.Topics["selections"]}
		case "help": return ExecResult{Out: "Usage: gmx help [<command>|<topic> [<subtopic> [...]]]\n"}
		default: return ExecResult{Out: data.Helps[first]}
		}
	}
	// more than one
	if first=="selections" {
		second:=topics[1]
		sub, ok:=data.Subtopics[second]
		if !ok {
			return ExecResult{ErrExtra: fmt.Sprintf("Help topic 'selections' has no subtopic '%s'\n", second), Exit:2}
		}
		if len(topics)>2 {
			return ExecResult{ErrExtra: fmt.Sprintf("Help topic 'selections %s' has no subtopics\n", second), Exit:2}
		}
		return ExecResult{Out: sub}
	}
	return ExecResult{ErrExtra: fmt.Sprintf("Help topic '%s' has no subtopics\n", first), Exit:2}
}
GO
"}

