package main

import (
	"fmt"
	"math"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// ---------- C-style formatting ----------
func cSpecial(v float64) (string, bool) {
	if math.IsNaN(v) {
		if math.Signbit(v) { return "-nan", true }
		return "nan", true
	}
	if math.IsInf(v, 1) { return "inf", true }
	if math.IsInf(v, -1) { return "-inf", true }
	return "", false
}
func formatE(v float64, prec int) string {
	if s, ok := cSpecial(v); ok { return s }
	return strconv.FormatFloat(v, 'e', prec, 64)
}
func formatF(v float64, prec int) string {
	if s, ok := cSpecial(v); ok { return s }
	return strconv.FormatFloat(v, 'f', prec, 64)
}
func formatG(v float64) string {
	if s, ok := cSpecial(v); ok { return s }
	if v == 0 {
		if math.Signbit(v) { return "-0" }
		return "0"
	}
	// scientific representation with 6 significant digits
	es := strconv.FormatFloat(v, 'e', 5, 64) // d.dddde±dd
	// parse exponent
	idx := strings.Index(es, "e")
	exp, _ := strconv.Atoi(es[idx+1:])
	if exp < -4 || exp >= 6 {
		mant := strings.TrimRight(es[:idx], "0")
		mant = strings.TrimRight(mant, ".")
		sign := "+"
		e := exp
		if e < 0 { sign="-"; e=-e }
		return fmt.Sprintf("%se%s%02d", mant, sign, e)
	}
	prec := 5 - exp
	fs := strconv.FormatFloat(v, 'f', prec, 64)
	fs = strings.TrimRight(fs, "0")
	fs = strings.TrimRight(fs, ".")
	return fs
}
func padField(s string, width int) string {
	if len(s) >= width { return s }
	return strings.Repeat(" ", width-len(s)) + s
}

// ---------- option value retrieval ----------
func optDefOf(cmd, name string) (OptionDef, bool) {
	for _, d := range data.Options[cmd] { if d.Name==name { return d, true } }
	return OptionDef{}, false
}
func getFloat(res *ParseResult, cmd, name string) float64 {
	var def float64
	if d, ok := optDefOf(cmd, name); ok && d.Default != nil {
		v, st := parseRealStr(*d.Default, "double"); _ = st; def = v
		if d.Prec=="float" { def = float64(float32(def)) }
	}
	if p := res.get(name); p != nil && len(p.Values)>0 {
		v, st := parseRealStr(p.Values[0], "double"); _=st
		if d, ok := optDefOf(cmd, name); ok && d.Prec=="float" { v = float64(float32(v)) }
		return v
	}
	return def
}
func getInt(res *ParseResult, cmd, name string) int {
	var def int
	if d, ok := optDefOf(cmd, name); ok && d.Default != nil { fmt.Sscanf(*d.Default, "%d", &def) }
	if p := res.get(name); p != nil && len(p.Values)>0 { fmt.Sscanf(p.Values[0], "%d", &def) }
	return def
}
func getStringOpt(res *ParseResult, cmd, name string) string {
	if d, ok := optDefOf(cmd, name); ok && d.Default != nil {
		if p := res.get(name); p != nil && len(p.Values)>0 { return p.Values[0] }
		return *d.Default
	}
	if p := res.get(name); p != nil && len(p.Values)>0 { return p.Values[0] }
	return ""
}
func getEnumOpt(res *ParseResult, cmd, name string) string { return getStringOpt(res, cmd, name) }
func getFileOpt(res *ParseResult, cmd, name string) string {
	if p := res.get(name); p != nil && len(p.Values)>0 {
		r:=res.resolved(name); if len(r)>0 { return r[0] }
		return p.Values[0]
	}
	if d, ok := optDefOf(cmd, name); ok && d.Default != nil {
		// if default file completion exists, use it, otherwise default name
		if resolved, ok2 := fileExistsWithCompletion(d); ok2 { return resolved }
		return *d.Default
	}
	return ""
}

// ---------- backup / output ----------
func backupIfExists(path string, enabled bool) string {
	if !enabled { return "" }
	if _, err := os.Stat(path); err != nil { return "" }
	dir := filepath.Dir(path)
	base := filepath.Base(path)
	for n:=1;;n++ {
		bname := fmt.Sprintf("#%s.%d#", base, n)
		bpath := bname
		if dir != "." { bpath = dir + "/" + bname } 
		if _, err := os.Stat(bpath); err != nil {
			// rename
			os.Rename(path, bpath)
			return fmt.Sprintf("\nBack Off! I just backed up %s to %s\n", path, bpath)
		}
	}
}
func fileIOErrorBlock(display, path string) *ErrorBlock {
	return &ErrorBlock{Program: display, Source: "src/gromacs/utility/futil.cpp", Line: 414, Heading: "File input/output error:", Body: path + "\n"}
}

// returns (backupMessage, errorBlock)
func writeOutput(path string, content string, backup bool, display string) (string, *ErrorBlock) {
	msg := ""
