{"command":"cat > /workspace/sigeps.go << 'GO'
package main

import (
	"fmt"
	"math"
	"strings"
)

func handleSigeps(res *ParseResult, display string) ExecResult {
	cmd := "sigeps"
	get := func(n string) float64 { return getFloat(res, cmd, n) }
	pow := getInt(res, cmd, "pow")
	buckSet := res.isSet("A") || res.isSet("B") || res.isSet("C")
	sigSet := res.isSet("sig") || res.isSet("eps")
	c6Set := res.isSet("c6") || res.isSet("cn") || res.isSet("pow")
	xvg := getEnumOpt(res, cmd, "xvg")
	outName := getFileOpt(res, cmd, "o")

	var sig, eps, c6, cn float64
	var A, B, C float64
	var out strings.Builder
	qi := get("qi"); qj := get("qj")
	sigfac := get("sigfac")

	if buckSet {
		A = get("A"); B = get("B"); C = get("C")
		// derive LJ sig/eps from B and C
		n := float64(pow)
		if pow == 6 {
			sig = (n / B)
		} else {
			sig = (n / B) * math.Pow(6.0/n, 1.0/(n-6.0))
		}
		c6 = C
		eps = c6 / (4.0 * math.Pow(sig, 6))
		cn = 4.0 * eps * math.Pow(sig, n)
		// A,B,C for buck column already set
		_ = sig
	} else {
		if sigSet {
			sig = get("sig"); eps = get("eps")
			c6 = 4.0 * eps * math.Pow(sig, 6)
			cn = 4.0 * eps * math.Pow(sig, float64(pow))
		} else if c6Set {
			c6 = get("c6"); cn = get("cn")
			sig = math.Pow(cn/c6, 1.0/(float64(pow)-6.0))
			eps = c6 / (4.0 * math.Pow(sig, 6))
		} else {
			c6 = get("c6"); cn = get("cn")
			sig = 0; eps = 0
		}
		// fit Buckingham
		n := float64(pow)
		var rmin float64
		if pow == 6 { rmin = 1 } else { rmin = sig * math.Pow(n/6.0, 1.0/(n-6.0)) }
		B = n / rmin
		A = 6.0*c6/(B*math.Pow(rmin, 7)) * math.Exp(B*rmin)
		C = c6
		// output lines
		out.WriteString(fmt.Sprintf("c6    = %s, c%d    = %s\n", padField(formatE(c6,5),12), pow, padField(formatE(cn,5),12)))
		out.WriteString(fmt.Sprintf("sigma = %s, epsilon = %s\n", padField(formatF(sig,5),12), padField(formatF(eps,5),12)))
		vmin := cn/math.Pow(rmin, n) - c6/math.Pow(rmin, 6)
		out.WriteString(fmt.Sprintf("Van der Waals minimum at %s, V = %s\n", formatG(rmin), formatG(vmin)))
		out.WriteString("\n")
		out.WriteString(fmt.Sprintf("Fit of Lennard Jones (%d-6) to Buckingham:\n", pow))
		out.WriteString(fmt.Sprintf("A = %s, B = %s, C = %s\n", formatG(A), formatG(B), formatG(C)))
		if qi*qj < 0 {
			// find minimum of LJ + Coulomb
			rC, vC := coulombMinimum(c6, cn, pow, qi, qj)
			out.WriteString(fmt.Sprintf("Van der Waals + Coulomb minimum at r = %s (nm). Value = %s (kJ/mol)\n", formatG(rC), formatG(vC)))
		}
	}
	// build file content
	var fileContent strings.Builder
	if xvg != "none" {
		fileContent.WriteString(xvgFileHeader(display, xvg))
		fileContent.WriteString("@    title \"Potential\"\n")
		fileContent.WriteString("@    xaxis  label \"r (nm)\"\n")
		fileContent.WriteString("@    yaxis  label \"E (kJ/mol)\"\n")
		if xvg == "xmgr" {
			fileContent.WriteString("@TYPE nxy\n")
		} else {
			fileContent.WriteString("@TYPE xy\n")
		}
		fileContent.WriteString("@ view 0.15, 0.15, 0.75, 0.85\n")
		fileContent.WriteString("@ legend on\n")
		fileContent.WriteString("@ legend box on\n")
		fileContent.WriteString("@ legend loctype view\n")
		fileContent.WriteString("@ legend 0.78, 0.8\n")
		fileContent.WriteString("@ legend length 2\n")
		if xvg == "xmgr" {
			fileContent.WriteString("@ legend string 0 \"Lennard-Jones\"\n")
			fileContent.WriteString("@ legend string 1 \"Buckingham\"\n")
		} else {
			fileContent.WriteString("@ s0 legend \"Lennard-Jones\"\n")
			fileContent.WriteString("@ s1 legend \"Buckingham\"\n")
		}
	}
	plotSig := sig
	if plotSig == 0 { plotSig = 0.25 }
	rstart := sigfac * plotSig
	step := plotSig / 50.0
	for i:=0;i<100;i++ {
		r := rstart + float64(i)*step
		vlj := cn*math.Pow(r, -float64(pow)) - c6*math.Pow(r, -6)
		vbuck := A*math.Exp(-B*r) - C*math.Pow(r, -6)
		fileContent.WriteString(fmt.Sprintf("%s %s %s\n", padField(formatG(r),10), padField(formatG(vlj),11), padField(formatG(vbuck),11)))
	}
	backupMsg, errBlock := writeOutput(outName, fileContent.String(), res.backupEnabled(), display)
	if errBlock != nil {
		return ExecResult{Block: errBlock, Exit: 1}
	}
	return ExecResult{Out: out.String(), ErrExtra: backupMsg, Exit: 0}
}

func coulombMinimum(c6, cn float64, pow int, qi, qj float64) (float64, float64) {
	const fc = 138.9354558 // ONE_4PI_EPS0 in kJ nm / (mol e^2) approx
	k := fc * qi * qj
	potential := func(r float64) float64 {
		return cn*math.Pow(r, -float64(pow)) - c6*math.Pow(r, -6) + k/r
	}
	// golden section search on log? Use ternary over interval bracketed by scanning
	lo, hi := 1e-4, 10.0
	// scan for bracket around global minimum in (lo,hi)
	bestR, bestV := lo, potential(lo)
	for i:=0;i<=4000;i++ {
		r := lo * math.Pow(hi/lo, float64(i)/4000.0)
		v:=potential(r)
		if v < bestV { bestV=v; bestR=r }
	}
	// refine around bestR multiplicative interval
	a := bestR*0.8; b := bestR*1.25
	for iter:=0; iter<200; iter++ {
		m1 := a + (b-a)*0.3819660112501051
		m2 := b - (b-a)*0.3819660112501051
		if potential(m1) < potential(m2) { b=m2 } else { a=m1 }
	}
	r := (a+b)/2
	return r, potential(r)
}
GO
"}

