cat > /workspace/check.go << 'GO'
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// GRO parsing
type AtomLine struct {
	Raw string
}
type GroFrame struct {
	Title string
	NAtoms int
	HasVel bool
	Box []float64
	Lines []string
}
func parseGroFile(path string) ([]GroFrame, string, error) {
	f, err:=os.Open(path); if err!=nil { return nil,"",err }
	defer f.Close()
	var frames []GroFrame
	scanner := bufio.NewScanner(f)
	// increase buffer
	buf:=make([]byte, 1024*1024); scanner.Buffer(buf, 10*1024*1024)
	lines:=[]string{}
	for scanner.Scan() { lines=append(lines, scanner.Text()) }
	idx:=0
	for idx < len(lines) {
		if idx>=len(lines) { break }
		title:=lines[idx]; idx++
		if idx>=len(lines) { break }
		n, err:=strconv.Atoi(strings.TrimSpace(lines[idx])); idx++
		if err!=nil {
			// mimic gro error handled by caller
			return frames, title, fmt.Errorf("gro file does not have the number of atoms on the second line")
		}
		fr:=GroFrame{Title:title, NAtoms:n}
		for a:=0;a<n && idx<len(lines);a++ {
			line:=lines[idx]; idx++; fr.Lines=append(fr.Lines,line)
			// velocities if line length > 44? gro vel columns after 44
			if len(line) > 44 { fr.HasVel=true }
		}
		if idx<len(lines) {
			boxline:=lines[idx]; idx++
			parts:=strings.Fields(boxline)
			for _,p:=range parts { if v,err:=strconv.ParseFloat(p,64); err==nil { fr.Box=append(fr.Box,v) } }
		}
		frames=append(frames, fr)
		if idx>=len(lines) { break }
	}
	return frames, "", nil
}

func handleCheckImpl(res *ParseResult, display string) ExecResult {
	// Handling in priority order observed from original:
	// If -c given: checking coordinate file; requires residuetypes.dat library
	// If -f / -f2 / -e / -e2 / -n / -s1 / -s2 supplied, process.
	// Simplified: implement -f for .gro trajectory, others fall back to library or generic messages.
	// Check -m latex removal message if -m set and nothing else (observed: check -m out.tex gave that message)
	// Gather supplied file options in a specific order? Original checks files in the order given? Observed single file cases.
	// We implement:
	// 1. if -c set: Check coordinate file
	if res.isSet("c") {
		name:=getFileOpt(res,"check","c")
		var errExtra strings.Builder
		errExtra.WriteString(fmt.Sprintf("Checking coordinate file %s\n", name))
		// library lookup
		if block:=libraryFileError(display, "residuetypes.dat"); block!=nil {
			// note original prints blank line before block? Our block starts with \n, and ErrExtra currently does not end with blank.
			// In captured -quiet run, Err was "Checking coordinate file test.gro\n\n----" (checking line, blank, block leading \n gives one blank? -quiet err: Checking... \n then block \n --- gives one blank)
			return ExecResult{ErrExtra: errExtra.String(), Block: block, Exit:1}
		}
		return ExecResult{ErrExtra: errExtra.String(), Exit:0}
	}
	if res.isSet("f") {
		name:=getFileOpt(res,"check","f")
		ext:=fileExtOf(name)
		if ext==".gro" || ext==".g96" || ext==".pdb" {
			frames, _, err:=parseGroFile(name)
			if err!=nil {
				// Fatal gro error
				block:=&ErrorBlock{Program:display, Source:"src/gromacs/fileio/groio.cpp", Line:66, Heading:"Fatal error:", Body: err.Error()+"\n"}
				// original for parse failure: reading frames line first?
				var pre string
				// For malformed gro, original stderr was "Reading frames from gro file\n--- Fatal"
				// Title unknown; approximate
				pre = "Reading frames from gro file\n"
				return ExecResult{Out: fmt.Sprintf("Checking file %s\n", name), ErrExtra: pre, Block:block, Exit:1}
			}
			var out strings.Builder; var errout strings.Builder
			out.WriteString(fmt.Sprintf("Checking file %s\n", name))
			if len(frames)>0 {
				errout.WriteString(fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n", frames[0].Title, frames[0].NAtoms))
			}
			velCount:=0
			for i,fr:=range frames {
				errout.WriteString(fmt.Sprintf("\nReading frame %7d time %8.3f   \n", i, 0.0))
				if i==0 {
					errout.WriteString(fmt.Sprintf("# Atoms  %d\n", fr.NAtoms))
					errout.WriteString("Precision 0.001 (nm)\n")
				}
				if fr.HasVel { velCount++ }
			}
			if len(frames)>0 {
				errout.WriteString(fmt.Sprintf("\nLast frame %10d time %8.3f   \n", len(frames)-1, 0.0))
			}
			errout.WriteString("\n\nItem        #frames Timestep (ps)\n")
			errout.WriteString("Step             0\n")
			errout.WriteString("Time             0\n")
			errout.WriteString("Lambda           0\n")
			errout.WriteString(fmt.Sprintf("Coords           %d\n", len(frames)))
			errout.WriteString(fmt.Sprintf("Velocities       %d\n", velCount))
			errout.WriteString("Forces           0\n")
			boxCount:=0; for _,fr:=range frames { if len(fr.Box)>0 { boxCount++ } }
			errout.WriteString(fmt.Sprintf("Box              %d\n", boxCount))
			return ExecResult{Out: out.String(), ErrExtra: errout.String(), Exit:0}
		}
		// unsupported trajectory extension that is recognisable-but? For .txt etc original gave Fatal trxio
		if ext!="" {
			// check if extension is in trajectory list; if not, original tried to read and gave trxio fatal for .txt-like
			block:=&ErrorBlock{Program:display, Source:"src/gromacs/fileio/trxio.cpp", Line:1088, Heading:"Fatal error:", Body: fmt.Sprintf("Not supported in read_first_frame: %s. Please make sure that the file is\na trajectory.\nGROMACS is not compiled with plug-in support. Thus it cannot read non-GROMACS\ntrajectory formats using the VMD plug-ins.\nPlease compile with plug-in support if you want to read non-GROMACS trajectory\nformats.\n", name)}
			return ExecResult{Out: fmt.Sprintf("Checking file %s\n", name), Block:block, Exit:1}
		}
		return ExecResult{Out: fmt.Sprintf("Checking file %s\n", name), Exit:0}
	}
	if res.isSet("m") {
		return ExecResult{ErrExtra: "LaTeX file writing has been removed from gmx check. Please use gmx report-methods instead for it.\n", Exit:0}
	}
	// No files: do nothing
	return ExecResult{Exit:0}
}

func libraryFileError(display, fname string) *ErrorBlock {
	// search current dir and GMXLIB dirs, default
	if _, err:=os.Stat(fname); err==nil { return nil }
	gmxlib:=os.Getenv("GMXLIB")
	paths:=[]string{}
	// current dir path as in original: absolute cwd
	paths=append(paths, fmt.Sprintf("  %s (current dir)", workingDir))
	if gmxlib!="" {
		for _,p:=range strings.Split(gmxlib, ":") { paths=append(paths, fmt.Sprintf("  %s", p)) }
	}
	paths=append(paths, "  /usr/local/gromacs/share/gromacs/top (default)")
	body:=fmt.Sprintf("Library file '%s' not found in current dir nor in the default\ndirectories.\nThe following paths were searched:\n%s\nYou can set additional directories to search with the GMXLIB path variable.\n", fname, strings.Join(paths,"\n"))
	return &ErrorBlock{Program:display, Source:"src/gromacs/utility/datafilefinder.cpp", Line:213, Func:"std::filesystem::__cxx11::path gmx::DataFileFinder::findFile(const gmx::DataFileOptions&) const", Heading:"System I/O error:", Body:body}
}
GO
"}

