	var out strings.Builder
	dt:=1.0
	if len(data)>=2 { dt=data[1][0]-data[0][0] }
	// dt formatting like %g?
	out.WriteString(fmt.Sprintf("Read %d sets of %d points, dt = %s\n", nsets, len(data), formatG(dt)))
	out.WriteString("\n")
	out.WriteString("                                      std. dev.    relative deviation of\n")
	out.WriteString("                       standard       ---------   cumulants from those of\n")
	out.WriteString("set      average       deviation      sqrt(n-1)   a Gaussian distribition\n")
	out.WriteString("                                                      cum. 3   cum. 4\n")
