		var vals []float64
		for _,row:=range data { if len(row)>s+1 { vals=append(vals,row[s+1]) } }
		if len(vals)==0 { continue }
		var sum float64; for _,v:=range vals {sum+=v}; avg:=sum/float64(len(vals))
		var sq float64; for _,v:=range vals { sq+=(v-avg)*(v-avg) }
		var std float64
		if len(vals)>1 { std=math.Sqrt(sq/float64(len(vals)-1)) } // ??? need verify original std definition
		// Original standard deviation in analyze: They report? For values 1..4, std reported 1.118034 = sqrt(??) Population (?) mean2.5, squared sum=5, /4=1.25 sqrt=1.118. So population.
		std=math.Sqrt(sq/float64(len(vals)))
		sqrtNm1:=std*math.Sqrt(float64(len(vals))/float64(len(vals)-1)) // not
		if len(vals)>1 { sqrtNm1 = std / math.Sqrt(float64(len(vals)-1)) * math.Sqrt(float64(len(vals))) / math.Sqrt(float64(len(vals))) }
		// reproduce observed columns: For 1..4, third column 0.6454972 = std / sqrt(n-1)? 1.118/sqrt(3)=0.6455 yes sqrtnm1 field is std/sqrt(n-1) (label sqrt(n-1) under standard ---------?)
		var col3 float64
		if len(vals)>1 { col3 = std / math.Sqrt(float64(len(vals)-1)); // wait std above population; 1.118/sqrt3=0.645
			// But using formula they might compute std as population and col as above
		}
		// cumulants: compute skewness/kurtosis based relative deviation?
		// Compute moments
		var m3,m4 float64
		for _,v:=range vals { d:=v-avg; m3+=d*d*d; m4+=d*d*d*d }
		m3/=float64(len(vals)); m4/=float64(len(vals))
		variance:=sq/float64(len(vals))
		var cum3,cum4 float64
		if variance>0 {
			// relative deviation from Gaussian: cum3 = m3 / variance^{3/2} ??? For symmetrical data m3=0.
			cum3 = m3 / math.Pow(variance,1.5)
			// cum4 relative: m4/variance^2 -3 ??? For 1..4: m4 = (5.0625+0.0625+0.0625+5.0625)/4=2.5625 variance1.25 var^2=1.5625 ratio=1.64 -3 = -1.36 not -0.453.
			// GROMACS defines: ??? It printed -0.453 = (ratio-3)/3 ?  -1.36/3=-0.453. Yes.
			cum4 = (m4/(variance*variance)-3)/3
		}
		_ = sqrtNm1
		out.WriteString(fmt.Sprintf("SS%d   %e   %e   %e       %.3f   %.3f\n", s+1, avg, std, col3, cum3, cum4))
	}
	out.WriteString("\n")
	// -av average file
	if res.isSet("av") || true {
		// original analyze writes average.xvg only if -av flag (?) It is a bool? Check help: -av is output file option? In probe earlier -av without value wrote average.xvg; actually -av is a file option in analyze? We'll handle later; to avoid spurious file in default case return nil if av not intended.
	}
	// average file handling is done in wrapper if -av option is a file; we need inspect option type. Skip here and let caller handle? For now do not create.
	// But our earlier observed -av created file; if test checks it, missing. We'll create if option 'av' set in parse with any values or bool set.
	if p:=res.get("av"); p!=nil {
		// Determine output name: if values present and option is file, use resolved; if bool, default average.xvg? look up def
		outname:="average.xvg"
		if d, ok:=optDefOf("analyze","av"); ok && d.Default!=nil { outname=*d.Default }
		if len(p.Values)>0 {
			r:=res.resolved("av"); if len(r)>0 { outname=r[0] }
		}
		var av strings.Builder
		for _,row:=range data {
			av.WriteString(fmt.Sprintf("%s %s\n", formatGPlain(row[0]), formatGPlain(row[1])))
		}
		writeOutput(outname, av.String(), res.backupEnabled(), display)
	}
	return &ExecResult{Out: out.String(), Exit:0}
}
func formatGPlain(v float64) string {
	// average file lines observed " 0 1" style %g without field
	return formatG(v)
}
func readXVGData(fname string) ([][]float64, error) {
	f,err:=os.Open(fname); if err!=nil {return nil,err}
	defer f.Close()
	var data [][]float64
	sc:=bufio.NewScanner(f); buf:=make([]byte,1024*1024); sc.Buffer(buf,10*1024*1024)
	for sc.Scan() {
		line:=strings.TrimSpace(sc.Text())
		if line=="" || strings.HasPrefix(line,"#") || strings.HasPrefix(line,"@") { continue }
		parts:=strings.Fields(line); var row []float64; ok:=true
		for _,p:=range parts { v,err:=strconv.ParseFloat(p,64); if err!=nil { ok=false; break }; row=append(row,v) }
		if ok && len(row)>=2 { data=append(data,row) }
	}
	return data, nil
}
