import subprocess, tempfile, re, math
def orig(args):
    with tempfile.TemporaryDirectory() as d:
        p=subprocess.run(["/workspace/executable","-quiet","sigeps"]+args, capture_output=True, text=True, cwd=d)
        m=re.search(r"at r = ([^ ]+) \(nm\)\. Value = ([^ ]+)",p.stdout)
        return tuple(float(x) for x in m.groups()) if m else None
def exact(c6,cn,n,K):
    def V(r): return cn*r**-n-c6*r**-6+K/r
    rs=[10**(-4+i*0.0005) for i in range(10000)]; r=min(rs,key=V)
    for _ in range(50):
        d=-n*cn*r**(-n-1)+6*c6*r**-7-K/r**2; dd=n*(n+1)*cn*r**(-n-2)-42*c6*r**-8+2*K/r**3; r-=d/dd
    return r,V(r)
for sig in [0.2,0.3,0.4,0.5]:
    c6=4*sig**6; cn=4*sig**12
    o=orig(["-sig",str(sig),"-eps","1","-qi","1","-qj","-1"])
    e=exact(c6,cn,12,-138.9354558)
    print(sig,o,e, "dr",o[0]-e[0])
for qi in [0.2,0.5,1,2]:
    o=orig(["-sig","0.3","-eps","1","-qi",str(qi),"-qj","-1"])
    e=exact(0.002916,2.12576e-06,12,-138.9354558*qi)
    print("qi",qi,o,e,o[0]-e[0])
PY"}

