import json, subprocess, re, concurrent.futures, gzip
EXE="/workspace/executable"
d=json.load(open("/tmp/generated_data.json"))
tasks=[]
for c,opts in d["options"].items():
    for o in opts:
        if o["kind"]=="enum": tasks.append((c,o["name"]))
def probe(t):
    c,name=t
    p=subprocess.run([EXE,"-quiet",c,f"-{name}","__bogus__"], capture_output=True, text=True, timeout=5)
    err=p.stderr
    idx=err.find("Allowed values:")
    if idx<0: return (c,name,None)
    seg=err[idx+len("Allowed values:"):]
    # until blank line
    seg=seg.split("\n\n")[0]
    # remove indentation and newlines
    seg=re.sub(r'\n\s+', ' ', seg).strip()
    if seg.endswith("."): seg=seg[:-1]
    vals=[x.strip() for x in seg.split(",") if x.strip()]
    return (c,name,vals)
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    for c,name,vals in ex.map(probe, tasks):
        if vals:
            for o in d["options"][c]:
                if o["name"]==name: o["allowed"]=vals
        else:
            print("no vals",c,name)
json.dump(d, open("/tmp/generated_data.json","w"))
open("/workspace/data.json.gz","wb").write(gzip.compress(json.dumps(d).encode(),9))
print("done")
# verify some
for cmd,opt in [("trjconv","pbc"),("rdf","selrpos")]:
    for o in d["options"][cmd]:
        if o["name"]==opt: print(cmd,o["allowed"])
