import subprocess, os, shutil, sys, concurrent.futures
ORIG="/workspace/executable"; CLONE="/tmp/clone_executable"
def run_one(pair):
    idx,args=pair
    work=f"/tmp/pcompare_{idx}/work"
    results=[]
    for exe in [ORIG,CLONE]:
        if os.path.exists(work): shutil.rmtree(os.path.dirname(work))
        os.makedirs(work)
        env=dict(os.environ); env["GMX_NO_QUOTES"]="1"
        try:
            p=subprocess.run(["./executable"]+args, executable=exe, capture_output=True, text=True, cwd=work, env=env, input="", timeout=10)
            rc,out,err=p.returncode,p.stdout,p.stderr
        except subprocess.TimeoutExpired:
            rc,out,err=-999,"","TIMEOUT"
        files={}
        for root,dirs,fs in os.walk(work):
            for f in fs:
                rel=os.path.relpath(os.path.join(root,f),work)
                txt=open(os.path.join(root,f),"rb").read().decode(errors="ignore")
                lines=[("#DATE" if l.startswith("# This file was created") else l) for l in txt.splitlines()]
                files[rel]="\n".join(lines)
        results.append((rc,out,err,files))
    o,c=results
    if o==c: return (args,True,"")
    msg=[]
    if o[0]!=c[0]: msg.append(f"exit {o[0]} vs {c[0]}")
    if o[1]!=c[1]:
        for i,(a,b) in enumerate(zip(o[1],c[1])):
            if a!=b: msg.append(f"stdout@{i} orig {o[1][max(0,i-60):i+120]!r} clone {c[1][max(0,i-60):i+120]!r}"); break
        else: msg.append(f"stdout len {len(o[1])} vs {len(c[1])} extra {o[1][len(c[1]):][:200]!r} {c[1][len(o[1]):][:200]!r}")
    if o[2]!=c[2]:
        for i,(a,b) in enumerate(zip(o[2],c[2])):
            if a!=b: msg.append(f"stderr@{i} orig {o[2][max(0,i-60):i+160]!r} clone {c[2][max(0,i-60):i+160]!r}"); break
        else: msg.append(f"stderr len {len(o[2])} vs {len(c[2])}")
    if o[3]!=c[3]: msg.append(f"files {list(o[3])} vs {list(c[3])} "+str({k:(o[3].get(k,'')[:200],c[3].get(k,'')[:200]) for k in set(o[3])|set(c[3]) if o[3].get(k)!=c[3].get(k)}))
    return (args,False,"\n  ".join(msg))

cases=eval(open("/tmp/cases.py").read())
ok=0; fails=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    for args,passed,msg in ex.map(run_one, list(enumerate(cases))):
        if passed: ok+=1
        else: fails.append((args,msg))
print(f"{ok}/{len(cases)} passed")
for a,m in fails: print("FAIL",a,"\n ",m)
