import subprocess, os, shutil, sys
ORIG="/workspace/executable"; CLONE="/tmp/clone_executable"
def run(exe,args,setup):
    work="/tmp/fcompare_work"
    if os.path.exists(work): shutil.rmtree(work)
    os.makedirs(work)
    for name,src in setup.items():
        if os.path.exists(src): shutil.copy(src, os.path.join(work,name))
        else: open(os.path.join(work,name),"w").write(src)
    env=dict(os.environ); env["GMX_NO_QUOTES"]="1"
    p=subprocess.run(["./executable"]+args, executable=exe, capture_output=True, text=True, cwd=work, env=env, input="", timeout=10)
    files={}
    for f in os.listdir(work):
        if f not in setup:
            txt=open(os.path.join(work,f),"rb").read().decode(errors="ignore")
            lines=[("#DATE" if l.startswith("# This file was created") else l) for l in txt.splitlines()]
            files[f]="\n".join(lines)
    return p.returncode,p.stdout,p.stderr,files
def compare(args,setup={}):
    o=run(ORIG,args,setup); c=run(CLONE,args,setup)
    print(("PASS" if o==c else "FAIL"),args)
