{"command":"cat > /workspace/genconf.go << 'GO'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type GroAtom struct {
	ResNr int
	ResName string
	AtomName string
	AtomNr int
	X,Y,Z float64
	VX,VY,VZ float64
	HasVel bool
}
func parseGroAtom(line string) (GroAtom, bool) {
	var a GroAtom
	if len(line) < 44 {
		// try fields
		f:=strings.Fields(line)
		if len(f)<6 { return a,false }
		// f: resnr+name combined difficult; give up
		return a,false
	}
	atoi:=func(s string) int { v,_:=strconv.Atoi(strings.TrimSpace(s)); return v }
	atof:=func(s string) float64 { v,_:=strconv.ParseFloat(strings.TrimSpace(s),64); return v }
	a.ResNr=atoi(line[0:5])
	a.ResName=strings.TrimSpace(line[5:10])
	a.AtomName=strings.TrimSpace(line[10:15])
	a.AtomNr=atoi(line[15:20])
	a.X=atof(line[20:28]); a.Y=atof(line[28:36]); a.Z=atof(line[36:44])
	if len(line)>=68 {
		a.VX=atof(line[44:52]); a.VY=atof(line[52:60]); a.VZ=atof(line[60:68]); a.HasVel=true
	}
	return a,true
}
func formatGroAtom(a GroAtom) string {
	return fmt.Sprintf("%5d%-5s%5s%5d%8.3f%8.3f%8.3f%8.4f%8.4f%8.4f", a.ResNr, a.ResName, a.AtomName, a.AtomNr, a.X,a.Y,a.Z, a.VX,a.VY,a.VZ)
}
func getVectorOpt(res *ParseResult, cmd, name string) [3]float64 {
	var out [3]float64
	if d,ok:=optDefOf(cmd,name); ok && d.Default!=nil {
		parts:=strings.Fields(*d.Default); for i,p:=range parts { if i<3 { out[i],_=strconv.ParseFloat(p,64)}}
	}
	if p:=res.get(name); p!=nil && len(p.Values)>0 {
		// vector can be 1 or 3 values
		if len(p.Values)==1 { v,_:=strconv.ParseFloat(p.Values[0],64); out=[3]float64{v,v,v} } else {
			for i,v:=range p.Values { if i<3 { out[i],_=strconv.ParseFloat(v,64)}}
		}
	}
	return out
}
func getIntVecOpt(res *ParseResult, cmd, name string) [3]int {
	var out [3]int
	if d,ok:=optDefOf(cmd,name); ok && d.Default!=nil {
		parts:=strings.Fields(*d.Default); for i,p:=range parts { if i<3 { fmt.Sscanf(p,"%d",&out[i])}}
	}
	if p:=res.get(name); p!=nil && len(p.Values)>0 {
		if len(p.Values)==1 { var v int; fmt.Sscanf(p.Values[0],"%d",&v); out=[3]int{v,v,v} } else { for i,v:=range p.Values { if i<3 { fmt.Sscanf(v,"%d",&out[i])}}}
	}
	return out
}

func handleGenconf(res *ParseResult, display string) *ExecResult {
	in:=getFileOpt(res,"genconf","f")
	if fileExtOf(in)!=".gro" { return nil }
	frames,_,err:=parseGroFile(in)
	if err!=nil || len(frames)==0 { return nil }
	fr:=frames[0]
	// parse atoms via columns
	var atoms []GroAtom
	for _,l:=range fr.Lines { if a,ok:=parseGroAtom(l); ok { atoms=append(atoms,a)} }
	if len(atoms)==0 { return nil }
	nbox:=getIntVecOpt(res,"genconf","nbox")
	dist:=getVectorOpt(res,"genconf","dist")
	renumber:=res.boolVal("renumber", true)
	box:=fr.Box
	if len(box)<3 { box=[]float64{0,0,0} }
	// total residues span
	maxRes:=0; minRes:=0
	for i,a:=range atoms { if i==0||a.ResNr>maxRes {maxRes=a.ResNr}; if i==0||a.ResNr<minRes {minRes=a.ResNr} }
	nResPer:=maxRes-minRes+1
	var outAtoms []GroAtom
	atomNr:=1
	copyIdx:=0
	for ix:=0;ix<nbox[0];ix++ {
		for iy:=0;iy<nbox[1];iy++ {
			for iz:=0;iz<nbox[2];iz++ {
				for _,a:=range atoms {
					na:=a
					na.X=a.X+float64(ix)*(box[0]+dist[0])
					na.Y=a.Y+float64(iy)*(box[1]+dist[1])
					na.Z=a.Z+float64(iz)*(box[2]+dist[2])
					if renumber { na.ResNr=a.ResNr+copyIdx*nResPer }
					na.AtomNr=atomNr; atomNr++
					outAtoms=append(outAtoms,na)
				}
				copyIdx++
			}
		}
	}
	var b strings.Builder
	b.WriteString(fr.Title+"\n")
	b.WriteString(fmt.Sprintf("%5d\n", len(outAtoms)))
	for _,a:=range outAtoms { b.WriteString(formatGroAtom(a)+"\n") }
	// box output
	if len(box)>=9 {
		// triclinic: scale diagonal by nbox, keep off diag?
		nb:=[]float64{box[0]*float64(nbox[0]), box[1]*float64(nbox[1]), box[2]*float64(nbox[2]), box[3],box[4],box[5],box[6],box[7],box[8]}
		for i,v:=range nb { if i>0 { b.WriteString(" ") }; b.WriteString(fmt.Sprintf("%10.5f",v)) }
		b.WriteString("\n")
	} else if len(box)>=3 {
		b.WriteString(fmt.Sprintf("%10.5f%10.5f%10.5f\n", box[0]*float64(nbox[0]), box[1]*float64(nbox[1]), box[2]*float64(nbox[2])))
	}
	outName:=getFileOpt(res,"genconf","o")
	msg, blk:=writeOutput(outName, b.String(), res.backupEnabled(), display)
	if blk!=nil { return &ExecResult{Block:blk,Exit:1} }
	return &ExecResult{ErrExtra:msg, Exit:0}
}
