func noteFor(cmd string) string {
	return fmt.Sprintf("Note that major changes are planned in future for %s, to improve usability and utility.\n", cmd)
}

func handleLegacy(cmd string, res *ParseResult, display string) *ExecResult {
	switch cmd {
	case "editconf":
		out := noteFor(cmd)
		// reads structure file; requires residuetypes
		if blk:=libraryFileError(display, "residuetypes.dat"); blk!=nil {
			return &ExecResult{Out:out, Block:blk, Exit:1}
		}
		return nil
	case "make_ndx":
		if !res.isSet("f") && !res.isSet("n") { return nil }
		nOld:=0
		if res.isSet("n") { nOld=len(res.values("n")) }
		out:=fmt.Sprintf("Going to read %d old index file(s)\nAnalysing residue names:\n", nOld)
		if res.isSet("f") {
			if blk:=libraryFileError(display, "residuetypes.dat"); blk!=nil {
				return &ExecResult{Out:out, ErrExtra:"\nReading structure file\n", Block:blk, Exit:1}
			}
		}
		return nil
	case "trjcat":
		out:=noteFor(cmd)
		// check input format
		if res.isSet("f") {
			for _,f:=range res.resolved("f") {
				ext:=fileExtOf(f)
				if ext==".gro" || ext==".g96" || ext==".pdb" {
					blk:=&ErrorBlock{Program:display, Source:"src/gromacs/tools/trjcat.cpp", Line:595, Heading:"Fatal error:", Body:"gmx trjcat can only handle binary trajectory formats (trr, xtc, tng)\n"}
					return &ExecResult{Out:out, Block:blk, Exit:1}
				}
			}
		}
		return nil
	case "trjconv":
		out:=noteFor(cmd)
		// output format message
		oname:=getFileOpt(res,"trjconv","o")
		ext:=fileExtOf(oname)
		formatDesc:=map[string]string{".gro":"gro: Coordinate file in Gromos-87 format", ".xtc":"xtc: Compressed trajectory (portable xdr format): xtc", ".trr":"trr: Full precision trajectory: trr", ".pdb":"pdb: Coordinate file in the PDB format"}
		desc,ok:=formatDesc[ext]; if !ok { desc=ext[1:]+": Trajectory file" }
		errExtra:=fmt.Sprintf("Will write %s\n", desc)
		// requires -s topology/structure; default topol.tpr
		sname:=getFileOpt(res,"trjconv","s")
		// if -s file does not exist on disk (getFileOpt returns default if absent)
		if !fileExists(sname) {
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/utility/futil.cpp", Line:458, Heading:"File input/output error:", Body:sname+"\n"}
			return &ExecResult{Out:out, ErrExtra:errExtra, Block:blk, Exit:1}
		}
		return nil
	case "convert-trj":
		// TRA: if no -s, reading frames then SetAtoms inconsistency for gro output
		if res.isSet("f") && !res.isSet("s") {
			fname:=getFileOpt(res,"convert-trj","f")
			if fileExtOf(fname)==".gro" {
				frames,_,err:=parseGroFile(fname)
				if err==nil && len(frames)>0 {
					pre:=fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n\nReading frame       0 time    0.000   \n", frames[0].Title, frames[0].NAtoms)
					blk:=&ErrorBlock{Program:display, Source:"src/gromacs/coordinateio/outputadapters/setatoms.cpp", Line:79, Func:"virtual void gmx::SetAtoms::processFrame(int, t_trxframe*)", Heading:"Inconsistency in user input:", Body:"Atoms needed by output but not available in input frame or topology\n"}
					return &ExecResult{ErrExtra:pre, Block:blk, Exit:1}
				}
			}
		}
		return nil
	}
	return nil
}
func fileExists(p string) bool {
	// use stat
	return p!="" && fileExistsPath(p)
}
