	energy:=make([]float64,nbins); for i,c:=range counts { if c>0 { energy[i]=-math.Log(float64(c)/float64(maxc)) } }
	// minima: occupied bins whose energy <= neighbours (occupied or all?) Simple: occupied bins that are local minima considering occupied bins sorted
	type Min struct{Bin int; Energy float64; Points []int}
	var mins []Min
	occ:=[]int{}; for i,c:=range counts { if c>0 {occ=append(occ,i)}}
	for _,b:=range occ {
		// local minimum if energy <= neighbouring occupied bins
		isMin:=true
		// find prev/next occupied
		// In observed, isolated bins all minima. If adjacent bins have lower energy (higher count), not.
		for _,ob:=range occ { if ob!=b && (ob==b-1 || ob==b+1) && energy[ob] < energy[b]-1e-12 { isMin=false } }
		if isMin {
			var pts []int; for i,bb:=range binOf { if bb==b { pts=append(pts,i+1)}}
			mins=append(mins, Min{b, energy[b], pts})
		}
	}
	out.WriteString(fmt.Sprintf("There are %d bins in the 1-dimensional histogram. Beta-Emin = %s\n", nbins, formatG(0)))
	out.WriteString(fmt.Sprintf("Ptot = %d\n", len(vals)))
	// ener.xvg (dist option)
	enerName:=getFileOpt(res,"sham","dist")
	var ener strings.Builder
	for _,m:=range mins {
		ener.WriteString(fmt.Sprintf("%5d  %10.5e  %10.5e  %10.5e\n", m.Bin, m.Energy, m.Energy, m.Energy))
	}
	// bindex.ndx (bin option)
	binName:=getFileOpt(res,"sham","bin")
	var ndx strings.Builder
	for _,m:=range mins {
		ndx.WriteString(fmt.Sprintf("[ %d ]\n", m.Bin))
		for _,p:=range m.Points { ndx.WriteString(fmt.Sprintf("%d\n", p)) }
	}
	// shamlog.log (g option)
	logName:=getFileOpt(res,"sham","g")
	var logb strings.Builder
	for i,m:=range mins { logb.WriteString(fmt.Sprintf("Minimum %d at index %d energy %10.3f\n", i, m.Bin, m.Energy)) }
	logb.WriteString("Minima sorted after energy\n")
	sortedMins:=append([]Min{}, mins...); sort.SliceStable(sortedMins, func(i,j int) bool {return sortedMins[i].Energy < sortedMins[j].Energy})
	for i,m:=range sortedMins { logb.WriteString(fmt.Sprintf("Minimum %d at index %d energy %10.3f\n", i, m.Bin, m.Energy)) }
	var backupMsgs strings.Builder
	for name,content:=range map[string]string{} { _=name; _=content }
	if msg,blk:=writeOutput(enerName, ener.String(), res.backupEnabled(), display); blk!=nil { return &ExecResult{Block:blk,Exit:1} } else { backupMsgs.WriteString(msg) }
	if msg,blk:=writeOutput(binName, ndx.String(), res.backupEnabled(), display); blk!=nil { return &ExecResult{Block:blk,Exit:1} } else { backupMsgs.WriteString(msg) }
	if msg,blk:=writeOutput(logName, logb.String(), res.backupEnabled(), display); blk!=nil { return &ExecResult{Block:blk,Exit:1} } else { backupMsgs.WriteString(msg) }
	return &ExecResult{Out:out.String(), ErrExtra:backupMsgs.String(), Exit:0}
}
