package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func handleCheckNdx(res *ParseResult, display string) ExecResult {
	name:=getFileOpt(res,"check","n")
	f,err:=os.Open(name)
	if err!=nil { return ExecResult{Exit:0} }
	defer f.Close()
	type Group struct{Name string; Entries []int}
	var groups []Group
	var cur *Group
	validFirst:=false
	sc:=bufio.NewScanner(f); buf:=make([]byte,1024*1024); sc.Buffer(buf,10*1024*1024)
	lineNo:=0
	for sc.Scan() {
		line:=strings.TrimSpace(sc.Text()); lineNo++
		if line=="" { continue }
		if strings.HasPrefix(line,"[") {
			end:=strings.Index(line,"]")
			if end<0 {
				// invalid
				if !validFirst {
					blk:=&ErrorBlock{Program:display, Source:"src/gromacs/topology/index.cpp", Line:730, Heading:"Fatal error:", Body:"The first header of your indexfile is invalid\n"}
					return ExecResult{Block:blk, Exit:1}
				}
				continue
			}
			gname:=strings.TrimSpace(line[1:end])
			groups=append(groups, Group{Name:gname})
			cur=&groups[len(groups)-1]
			validFirst=true
			continue
		}
		if !validFirst {
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/topology/index.cpp", Line:730, Heading:"Fatal error:", Body:"The first header of your indexfile is invalid\n"}
			return ExecResult{Block:blk, Exit:1}
		}
		if cur!=nil {
			// re-get cur pointer may be invalid after append? we set each header, entries appended via index
			for _,tok:=range strings.Fields(line) {
				if v,err:=strconv.Atoi(tok); err==nil { groups[len(groups)-1].Entries=append(groups[len(groups)-1].Entries, v) }
			}
		}
	}
	// check empty groups -> original segfaults; approximate by returning special result handled in main via Crash flag
	for _,g:=range groups {
		if len(g.Entries)==0 {
			// build output up to header
			var out strings.Builder
			out.WriteString(fmt.Sprintf("Contents of index file %s\n", name))
			out.WriteString("--------------------------------------------------\n")
			out.WriteString("Nr.   Group               #Entries   First    Last\n")
			// rows before empty
			for i,gg:=range groups {
				if len(gg.Entries)==0 { break }
				out.WriteString(fmt.Sprintf("%4d  %-20s %7d %7d %7d\n", i, gg.Name, len(gg.Entries), gg.Entries[0], gg.Entries[len(gg.Entries)-1]))
			}
			return ExecResult{Out:out.String(), Exit:139, SuppressFinal:true, Crash:true}
		}
	}
	var out strings.Builder
	out.WriteString(fmt.Sprintf("Contents of index file %s\n", name))
	out.WriteString("--------------------------------------------------\n")
	out.WriteString("Nr.   Group               #Entries   First    Last\n")
	for i,g:=range groups {
		out.WriteString(fmt.Sprintf("%4d  %-20s %7d %7d %7d\n", i, g.Name, len(g.Entries), g.Entries[0], g.Entries[len(g.Entries)-1]))
	}
	return ExecResult{Out:out.String(), Exit:0}
}
