func isStructExt(name string) bool {
	switch fileExtOf(name) {
	case ".gro",".g96",".pdb",".brk",".ent",".esp":
		return true
	}
	return false
}

func genericLibraryFallback(cmd string, res *ParseResult, display string) *ExecResult {
	blk:=libraryFileError(display, "residuetypes.dat")
	if blk==nil { return nil }
	// Trajectory analysis: explicit -s structure file
	if na,ok:=data.NoArgs[cmd]; ok && strings.Contains(na.Err, "runnercommon.cpp") {
