{"command":"cat > /workspace/tra.go << 'GO'
package main

import (
	"fmt"
	"strings"
)

var traCommands = map[string]bool{"convert-trj":true,"distance":true,"dssp":true,"freevolume":true,"gangle":true,"gyrate":true,"hbond":true,"msd":true,"pairdist":true,"rdf":true,"sasa":true,"scattering":true,"select":true,"trajectory":true}

func selectionOptionError(display string) *ErrorBlock {
	return &ErrorBlock{Program:display, Source:"src/gromacs/selection/selectionoption.cpp", Line:107, Func:"void gmx::SelectionOptionStorage::addSelections(const SelectionList&, bool)", Heading:"Error in user input:", Body:"Too few selections provided\n"}
}
func selectionCollectionError(display string) *ErrorBlock {
	return &ErrorBlock{Program:display, Source:"src/gromacs/selection/selectioncollection.cpp", Line:404, Func:"gmx::SelectionList gmx::{anonymous}::runParser(yyscan_t, gmx::TextInputStream*, bool, int, const string&)", Heading:"Error in user input:", Body:"Too few selections provided; got 0, expected 1\n"}
}
func initTopologyError(display string) *ErrorBlock {
	return &ErrorBlock{Program:display, Source:"src/gromacs/trajectoryanalysis/runnercommon.cpp", Line:193, Func:"void gmx::TrajectoryAnalysisRunnerCommon::Impl::initTopology(bool)", Heading:"Inconsistency in user input:", Body:"No topology provided, but one is required for analysis\n"}
}
func selectionRequiresTopology(sel string) bool {
	keywords:=[]string{"name","resname","resid","resnr","residue","chain","element","atomtype","type","mass","charge","beta","occupancy","group","molname","molnr"}
	fields:=strings.FieldsFunc(sel, func(r rune) bool { return r==' '||r=='('||r==')'||r==';'||r=='<'||r=='>'||r=='='||r==',' })
	for _,f:=range fields {
		lf:=strings.ToLower(f)
		for _,k:=range keywords { if lf==k { return true } }
	}
	return false
}
func frameSummaryGro(frames []GroFrame) string {
	var b strings.Builder
	if len(frames)==0 { return "" }
	b.WriteString(fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n", frames[0].Title, frames[0].NAtoms))
	for i:=range frames {
		b.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", i, 0.0))
	}
	b.WriteString(fmt.Sprintf("\rLast frame %10d time %8.3f   \n", len(frames)-1, 0.0))
	b.WriteString(fmt.Sprintf("Analyzed %d frames, last time 0.000\n", len(frames)))
	return b.String()
}

func handleTRA(cmd string, res *ParseResult, display string) *ExecResult {
	if !traCommands[cmd] { return nil }
	if res.isSet("s") { return nil } // generic library / other handles
	if !res.isSet("f") { return nil }
	fname:=getFileOpt(res, cmd, "f")
	if fileExtOf(fname)!=".gro" { return nil }
	// collect selection option names
	var selNames []string
	for _,d:=range data.Options[cmd] { if d.Kind=="selection" && d.Name!="fgroup" { selNames=append(selNames, d.Name) } }
	hasSel:=false; var selValues []string
	for _,n:=range selNames { if res.isSet(n) { hasSel=true; selValues=append(selValues, res.values(n)...) } }
	// special default-selection tools
	if cmd=="convert-trj" {
		frames,_,err:=parseGroFile(fname); if err!=nil {return nil}
		return &ExecResult{ErrExtra: frameSummaryGro(frames), Exit:0}
	}
	if cmd=="dssp" && !hasSel {
		blk:=&ErrorBlock{Program:display, Source:"src/gromacs/selection/selectioncollection.cpp", Line:702, Func:"void gmx::SelectionCollection::setIndexGroups(gmx_ana_indexgrps_t*)", Heading:"Inconsistency in user input:", Body:"Invalid index group reference(s)\n  Cannot match 'group \"Protein\"', because no such index group can be found.\n"}
		return &ExecResult{Block:blk, Exit:1}
	}
	if cmd=="freevolume" && !hasSel {
		blk:=initTopologyError(display); return &ExecResult{Block:blk, Exit:1}
	}
	if !hasSel || len(selValues)==0 {
		// category per tool
		switch cmd {
		case "gyrate","hbond","pairdist","rdf","sasa":
			return &ExecResult{Block:selectionCollectionError(display), Exit:1}
		default:
			return &ExecResult{Block:selectionOptionError(display), Exit:1}
		}
	}
	// selection supplied: only handle select/trajectory fully
	if cmd=="select" || cmd=="trajectory" {
		for _,sel:=range selValues {
			if selectionRequiresTopology(sel) { return &ExecResult{Block:initTopologyError(display), Exit:1} }
		}
		frames,_,err:=parseGroFile(fname); if err!=nil { return nil }
		// none selection: compile error after first frame
		for _,sel:=range selValues {
			if strings.TrimSpace(sel)=="none" {
				var pre strings.Builder
				pre.WriteString(fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n", frames[0].Title, frames[0].NAtoms))
				pre.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", 0, 0.0))
				blk:=&ErrorBlock{Program:display, Source:"src/gromacs/selection/selectioncollection.cpp", Line:877, Func:"void gmx::SelectionCollection::compile()", Heading:"Error in user input:", Body:fmt.Sprintf("Selection '%s' never matches any atoms.\n", sel)}
				return &ExecResult{ErrExtra:pre.String(), Block:blk, Exit:1}
			}
		}
		return &ExecResult{ErrExtra: frameSummaryGro(frames), Exit:0}
	}
	return nil
}
