{"command":"cat > /workspace/selection.go << 'GO'
package main

import "strings"

type selToken struct {Text string; Kind string} // id,num,str,op

func tokenizeSelection(s string) ([]selToken, string) {
	var toks []selToken
	i:=0
	for i<len(s) {
		c:=s[i]
		if c==' '||c=='\t'||c=='\n'||c=='\r' { i++; continue }
		if c=='"' {
			j:=i+1; for j<len(s) && s[j]!='"' { j++ }
			if j>=len(s) { return toks, "\"" }
			toks=append(toks, selToken{s[i:j+1],"str"}); i=j+1; continue
		}
		if c=='\'' { return toks, "'" }
		if c>='0'&&c<='9' || (c=='.' && i+1<len(s) && s[i+1]>='0' && s[i+1]<='9') {
			j:=i; for j<len(s) && ((s[j]>='0'&&s[j]<='9')||s[j]=='.') { j++ }
			// exponent
			if j<len(s) && (s[j]=='e'||s[j]=='E') { k:=j+1; if k<len(s)&&(s[k]=='+'||s[k]=='-'){k++}; for k<len(s)&&s[k]>='0'&&s[k]<='9'{k++}; j=k }
			toks=append(toks, selToken{s[i:j],"num"}); i=j; continue
		}
		if (c>='A'&&c<='Z')||(c>='a'&&c<='z')||c=='_' {
			j:=i; for j<len(s) && ((s[j]>='A'&&s[j]<='Z')||(s[j]>='a'&&s[j]<='z')||(s[j]>='0'&&s[j]<='9')||s[j]=='_') {j++}
			toks=append(toks, selToken{s[i:j],"id"}); i=j; continue
		}
		// operators two char
		if i+1<len(s) {
			two:=s[i:i+2]
			if two=="<="||two==">="||two=="=="||two=="!=" { toks=append(toks, selToken{two,"op"}); i+=2; continue }
		}
		if strings.ContainsRune("<>=+-*/^(),;", rune(c)) { toks=append(toks, selToken{string(c),"op"}); i++; continue }
		// invalid char
		return toks, string(c)
	}
	return toks, ""
}

// validateSelectionSyntax returns (near, isInvalid). near may be "".
func validateSelectionSyntax(v string) (string, bool) {
	trim:=strings.TrimSpace(v)
	if trim=="" { return "", false } // not handled
	toks, bad:=tokenizeSelection(v)
	if bad!="" {
		// '!' alone also here
		return bad, true
	}
	if len(toks)==0 { return "", false }
	// parenthesis balance
	open:=0; var lastTok string
	for _,t:=range toks {
		lastTok=t.Text
		if t.Text=="(" { open++ } else if t.Text==")" {
			open--
			if open<0 { return ")", true }
		}
	}
	if open>0 { return lastTok, true }
	lower:=func(s string) string { return strings.ToLower(s) }
	// start / end combinators
	if toks[0].Kind=="id" {
		if l:=lower(toks[0].Text); l=="and"||l=="or" { return toks[0].Text, true }
	}
	if toks[len(toks)-1].Kind=="id" {
		if l:=lower(toks[len(toks)-1].Text); l=="and"||l=="or"||l=="not"||l=="of"||l=="from"||l=="to"||l=="as" { return toks[len(toks)-1].Text, true }
	}
	if last:=toks[len(toks)-1]; last.Kind=="op" && (last.Text=="<"||last.Text==">"||last.Text=="="||last.Text=="+"||last.Text=="-"||last.Text=="*"||last.Text=="/"||last.Text=="^"||last.Text=="<="||last.Text==">="||last.Text=="==") {
		return last.Text, true
	}
	// single keyword requiring argument
	if len(toks)==1 && toks[0].Kind=="id" {
		req:=map[string]bool{"atomnr":true,"mol":true,"molecule":true,"molindex":true,"resid":true,"residue":true,"resindex":true,"resnr":true,"beta":true,"betafactor":true,"charge":true,"mass":true,"occupancy":true,"x":true,"y":true,"z":true,"altloc":true,"atomname":true,"atomtype":true,"chain":true,"insertcode":true,"name":true,"pdbatomname":true,"pdbname":true,"resname":true,"type":true}
		if req[lower(toks[0].Text)] { return toks[0].Text, true }
		return "", false
	}
	// first token unknown identifier, followed by another primary/of/to token
	known:=map[string]bool{"all":true,"none":true,"atomnr":true,"mol":true,"molecule":true,"molindex":true,"resid":true,"residue":true,"resindex":true,"resnr":true,"beta":true,"betafactor":true,"charge":true,"mass":true,"occupancy":true,"x":true,"y":true,"z":true,"altloc":true,"atomname":true,"atomtype":true,"chain":true,"insertcode":true,"name":true,"pdbatomname":true,"pdbname":true,"resname":true,"type":true,"and":true,"or":true,"not":true,"to":true,"of":true,"from":true,"as":true,"same":true,"within":true,"cog":true,"com":true,"merge":true,"plus":true,"permute":true,"insolidangle":true,"distance":true,"mindistance":true,"pbc":true,"true":true,"false":true}
	if len(toks)>=2 && toks[0].Kind=="id" && !known[lower(toks[0].Text)] {
		second:=toks[1]
		if second.Kind=="id" || second.Kind=="num" || second.Kind=="str" {
			// allow group followed by operators only, handled above; here second is primary
			return second.Text, true
		}
	}
	// '!' as standalone op token is handled by tokenizer as bad (since not in valid ops and not <= etc)
	return "", false
}
