package main

import "fmt"

func handleSpecific(cmd string, res *ParseResult, display string) *ExecResult {
	switch cmd {
	case "densmap":
		if res.isSet("s") { return nil }
		// default topol.tpr is attempted to be opened
		sname:=getFileOpt(res,"densmap","s")
		if !fileExists(sname) {
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/utility/futil.cpp", Line:458, Heading:"File input/output error:", Body:sname+"\n"}
			return &ExecResult{Block:blk, Exit:1}
		}
	case "mindist":
		if !res.isSet("n") && !res.isSet("s") {
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/gmxana/gmx_mindist.cpp", Line:872, Heading:"Fatal error:", Body:"You have to specify either the index file or a tpr file\n"}
			return &ExecResult{Block:blk, Exit:1}
		}
	case "clustsize":
		if res.isSet("f") && !res.isSet("n") {
			fname:=getFileOpt(res,"clustsize","f")
			if fileExtOf(fname)==".gro" {
				frames,_,err:=parseGroFile(fname); if err!=nil { return nil }
				var pre string
				if len(frames)>0 { pre=fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n\rReading frame %7d time %8.3f   ", frames[0].Title, frames[0].NAtoms, 0, 0.0) }
				blk:=&ErrorBlock{Program:display, Source:"src/gromacs/topology/index.cpp", Line:950, Heading:"Fatal error:", Body:"No index file specified\n"}
				// output xvg files are created empty before this in original
				for _,on := range []string{"av","max","n","temp"} {
					// option names in clustsize for these outputs vary; use defaults directly
					_ = on
				}
				// Create empty output files as original does (defaults)
				for _,fn := range []string{"avclust.xvg","maxclust.xvg","nclust.xvg","temp.xvg"} { writeOutput(fn,"",res.backupEnabled(),display) }
				return &ExecResult{ErrExtra:pre, Block:blk, Exit:1}
			}
		}
	}
	return nil
}
