package main

// MT19937-64 implementation (standard algorithm) used to reproduce the
// original programme's time-based quote selection, which was observed to use
// a 64-bit Mersenne Twister seeded with the current time in seconds and a
// uniform integer distribution over the quote list.
type mt19937_64 struct {
	mt [312]uint64
	index int
}

func newMT19937_64(seed uint64) *mt19937_64 {
	m := &mt19937_64{index: 312}
	m.mt[0]=seed
	for i:=1;i<312;i++ {
		prev:=m.mt[i-1]
		m.mt[i]=6364136223846793005*(prev^(prev>>62))+uint64(i)
	}
	return m
}
func (m *mt19937_64) generate() {
	const n=312; const mm=156
	for i:=0;i<n;i++ {
		x:=(m.mt[i]&0xFFFFFFFF80000000) | (m.mt[(i+1)%n]&0x7FFFFFFF)
		var xA uint64
		if x&1 !=0 { xA=(x>>1)^0xB5026F5AA96619E9 } else { xA=x>>1 }
		m.mt[i]=m.mt[(i+mm)%n]^xA
	}
	m.index=0
}
func (m *mt19937_64) next() uint64 {
	if m.index>=312 { m.generate() }
	y:=m.mt[m.index]; m.index++
	y ^= (y>>29)&0x5555555555555555
	y ^= (y<<17)&0x71D67FFFEDA60000
	y ^= (y<<37)&0xFFF7EEE000000000
	y ^= (y>>43)
	return y
}

// uniformInt911 mimics libstdc++ std::uniform_int_distribution<int>(0,910)
// for mt19937_64: scaling division with rejection of the tail.
func quoteIndexForTime(sec int64) int {
	gen:=newMT19937_64(uint64(sec))
	const uerange uint64 = 911
	const urng uint64 = 0xFFFFFFFFFFFFFFFF
	scaling:=urng/uerange
	past:=uerange*scaling
	for {
		x:=gen.next()
		if x < past {
			return int(x/scaling)
		}
	}
}
