	y ^= (y>>29)&0x5555555555555555
	y ^= (y<<17)&0x71D67FFFEDA60000
	y ^= (y<<37)&0xFFF7EEE000000000
	y ^= (y>>43)
	return y
}

// uniformInt911 mimics libstdc++ std::uniform_int_distribution<int>(0,910)
// for mt19937_64: scaling division with rejection of the tail.
func quoteIndexForTime(sec int64) int {
	gen:=newMT19937_64(uint64(sec))
	const uerange uint64 = 911
	const urng uint64 = 0xFFFFFFFFFFFFFFFF
	scaling:=urng/uerange
	past:=uerange*scaling
	for {
		x:=gen.next()
		if x < past {
			return int(x/scaling)
		}
	}
}
