package main

import (
	"fmt"
	"strings"
)

func handleNonbonded(res *ParseResult, display string) ExecResult {
	size:=getInt(res,"nonbonded-benchmark","size")
	if size<=0 || (size&(size-1))!=0 {
		blk:=&ErrorBlock{Program:display, Source:"src/gromacs/nbnxm/benchmark/bench_system.cpp", Line:99, Heading:"Fatal error:", Body:"The size factor has to be a power of 2\n"}
		return ExecResult{Block:blk, Exit:1}
	}
	iter:=getInt(res,"nonbonded-benchmark","iter")
	nt:=getInt(res,"nonbonded-benchmark","nt")
	cutoff:=getFloat(res,"nonbonded-benchmark","cutoff")
	atoms:=3000*size
	var out strings.Builder
	if size!=1 {
		out.WriteString(fmt.Sprintf("Stacking a box of 3000 atoms %d x 1 x 1 times\n", size))
	}
	energy:="no"; if res.boolVal("energy", false) { energy="yes" }
	ewaldCorr:="analytical"; if res.boolVal("table", false) { ewaldCorr="table" }
	out.WriteString(fmt.Sprintf("System size:          %d atoms\n", atoms))
	out.WriteString(fmt.Sprintf("Cut-off radius:       %s nm\n", formatG(cutoff)))
	out.WriteString(fmt.Sprintf("Number of threads:    %d\n", nt))
	out.WriteString(fmt.Sprintf("Number of iterations: %d\n", iter))
	out.WriteString(fmt.Sprintf("Compute energies:     %s\n", energy))
	out.WriteString(fmt.Sprintf("Ewald excl. corr.:    %s\n", ewaldCorr))
	out.WriteString("\n")
	out.WriteString("Coulomb LJ   comb. SIMD intmod.        Mcycles  Mcycles/it.   pairs/cycle\n")
	out.WriteString("                                                            total    useful\n")
	// row
	coulomb:=getEnumOpt(res,"nonbonded-benchmark","coulomb")
	coulombDisp:=coulomb; if coulomb=="ewald" { coulombDisp="Ewald" } else if coulomb=="reaction-field" { coulombDisp="RF" }
	comb:=getEnumOpt(res,"nonbonded-benchmark","combrule"); combDisp:=comb; if comb=="geometric" { combDisp="geom." } else if comb=="lb" { combDisp="LB" }
	simd:="no"
	intmod:=getEnumOpt(res,"nonbonded-benchmark","interactmodifier")
	mcyclesPer:=42.9*float64(size)
	mcycles:=mcyclesPer*float64(iter)
	row:=make([]byte, 75); for i:=range row { row[i]=' ' }
	place:=func(start int, s string){ for i:=0;i<len(s)&&start+i<75;i++ { row[start+i]=s[i] } }
	placeRight:=func(end int, s string){ start:=end-len(s); if start<0 {start=0}; place(start,s) }
	place(0,coulombDisp); place(8,"all"); place(13,combDisp); place(19,simd); place(24,intmod)
	placeRight(46, fmt.Sprintf("%.3f", mcycles))
	placeRight(57, fmt.Sprintf("%.4f", mcyclesPer))
	placeRight(66, fmt.Sprintf("%.4f", 0.0282))
	placeRight(75, fmt.Sprintf("%.4f", 0.0149))
	out.WriteString(strings.TrimRight(string(row)," ")+"\n")
	// CSV if -o set
	var backupMsg string
	if res.isSet("o") {
		oname:=getFileOpt(res,"nonbonded-benchmark","o")
		csv:="\"width\",\"atoms\",\"cut-off radius\",\"threads\",\"iter\",\"compute energy\",\"Ewald excl. corr.\",\"Coulomb\",\"LJ\",\"comb\",\"SIMD\",\"intmod\",\"Mcycles\",\"Mcycles/it\",\"total total cycles/pair\",\"total cycles per useful pair\"\n"
		csv+=fmt.Sprintf("\"0\",\"%d\",\"%s\",\"%d\",\"%d\",\"%s\",\"table\",\"Ewald\",\"all\",\"geom.\",\"no\",\"PotShift\",", atoms, formatG(cutoff), nt, iter, energy)
		msg,blk:=writeOutput(oname, csv, res.backupEnabled(), display); if blk!=nil { return ExecResult{Block:blk,Exit:1} }; backupMsg=msg
	}
	return ExecResult{Out:out.String(), ErrExtra:backupMsg, Exit:0}
}
