package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type NdxGroup struct{Name string; Entries []int}

func parseNdxFile(path string) ([]NdxGroup, error) {
	f,err:=os.Open(path); if err!=nil {return nil,err}
	defer f.Close()
	var groups []NdxGroup
	sc:=bufio.NewScanner(f); buf:=make([]byte,1024*1024); sc.Buffer(buf,10*1024*1024)
	for sc.Scan() {
		line:=strings.TrimSpace(sc.Text())
		if line=="" {continue}
		if strings.HasPrefix(line,"[") {
			end:=strings.Index(line,"]"); if end<0 {continue}
			groups=append(groups, NdxGroup{Name:strings.TrimSpace(line[1:end])})
			continue
		}
		if len(groups)>0 {
			for _,tok:=range strings.Fields(line) { if v,err:=strconv.Atoi(tok); err==nil { groups[len(groups)-1].Entries=append(groups[len(groups)-1].Entries, v)}}
		}
	}
	return groups, nil
}
func writeNdxFile(path string, groups []NdxGroup) string {
	var b strings.Builder
	for _,g:=range groups {
		b.WriteString(fmt.Sprintf("[ %s ]\n", g.Name))
		for i,entry:=range g.Entries {
			// 15 per line, each %4d
			b.WriteString(fmt.Sprintf("%4d", entry))
			if (i+1)%15==0 || i==len(g.Entries)-1 { b.WriteString("\n") }
		}
	}
	return b.String()
}
const makeNdxMenu = " nr : group      '!': not  'name' nr name   'splitch' nr    Enter: list groups\n 'a': atom       '&': and  'del' nr         'splitres' nr   'l': list residues\n 't': atom type  '|': or   'keep' nr        'splitat' nr    'h': help\n 'r': residue              'res' nr         'chain' char\n \"name\": group             'case': case sensitive           'q': save and quit\n 'ri': residue index\n"
const makeNdxHelp = " nr                : selects an index group by number or quoted string.\n                     The string is first matched against the whole group name,\n                     then against the beginning and finally against an\n                     arbitrary substring. A multiple match is an error.\n 'a' nr1 [nr2 ...] : selects atoms, atom numbering starts at 1.\n 'a' nr1 - nr2     : selects atoms in the range from nr1 to nr2.\n 'a' name1[*] [name2[*] ...] : selects atoms by name(s), '?' matches any char,\n                               wildcard '*' allowed at the end of a name.\n 't' type1[*] [type2[*] ...] : as 'a', but for type, run input file required.\n 'r' nr1[ic1] [nr2[ic2] ...] : selects residues by number and insertion code.\n 'r' nr1 - nr2               : selects residues in the range from nr1 to nr2.\n 'ri' nr1 - nr2              : selects residue indices, 1-indexed, (as opposed to numbers) in the range from nr1 to nr2.\n 'chain' ch1 [ch2 ...]       : selects atoms by chain identifier(s),\n                               not available with a .gro file as input.\n !                 : takes the complement of a group with respect to all\n                     the atoms in the input file.\n & |               : AND and OR, can be placed between any of the options\n                     above, the input is processed from left to right.\n 'name' nr name    : rename group nr to name.\n 'del' nr1 [- nr2] : deletes one group or groups in the range from nr1 to nr2.\n 'keep' nr         : deletes all groups except nr.\n 'case'            : make all name compares case (in)sensitive.\n 'splitch' nr      : split group into chains using CA distances.\n 'splitres' nr     : split group into residues.\n 'splitat' nr      : split group into atoms.\n 'res' nr          : interpret numbers in group as residue numbers\n Enter             : list the currently defined groups and commands\n 'l'               : list the residues.\n 'h'               : show this help.\n 'q'               : save and quit.\n\n Examples:\n > 2 | 4 & r 3-5\n selects all atoms from group 2 and 4 that have residue numbers 3, 4 or 5\n > a C* & !a C CA\n selects all atoms starting with 'C' but not the atoms 'C' and 'CA'\n > \"protein\" & ! \"backb\"\n selects all atoms that are in group 'protein' and not in group 'backbone'\n"

func groupListString(groups []NdxGroup) string {
	var b strings.Builder
	b.WriteString("\n")
	for i,g:=range groups {
		b.WriteString(fmt.Sprintf("%3d %-20s: %5d atoms\n", i, g.Name, len(g.Entries)))
	}
	b.WriteString("\n")
	b.WriteString(makeNdxMenu)
	return b.String()
}

func handleMakeNdx(res *ParseResult, display string) *ExecResult {
	if res.isSet("f") { return nil } // legacy library path handles it
	if !res.isSet("n") { return nil }
	// read index files
	var groups []NdxGroup
	nFiles:=0
	for _,fname:=range res.resolved("n") {
		gs,err:=parseNdxFile(fname); if err!=nil { continue }
		groups=append(groups, gs...); nFiles++
	}
	// count from values if resolved missing? use set count
	if nFiles==0 { nFiles=len(res.values("n")) }
	maxAtom:=0; for _,g:=range groups { for _,e:=range g.Entries { if e>maxAtom {maxAtom=e}}}
	var out strings.Builder
	out.WriteString(fmt.Sprintf("Going to read %d old index file(s)\n", len(res.values("n"))))
	out.WriteString(fmt.Sprintf("Deducing %d atoms in the system from indices in the index file\n", maxAtom))
	out.WriteString(groupListString(groups))
	// interactive loop reading all stdin lines
	reader:=bufio.NewReader(os.Stdin)
	save:=false
	for {
		out.WriteString("\n> ")
		line, err:=reader.ReadString('\n')
		if err!=nil && line=="" {
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/tools/make_ndx.cpp", Line:1149, Heading:"Fatal error:", Body:"Error reading user input\n"}
			return &ExecResult{Out:out.String(), Block:blk, Exit:1}
		}
		line=strings.TrimSpace(line)
		out.WriteString("\n")
		if line=="q" { save=true; break }
		if line=="" {
			out.WriteString(groupListString(groups)); continue
		}
		if line=="h" {
			out.WriteString(makeNdxHelp); continue
		}
		// commands
		toks:=strings.Fields(line)
		if len(toks)==0 { continue }
		switch toks[0] {
		case "del":
			if len(toks)>=2 {
				if nr,err:=strconv.Atoi(toks[1]); err==nil && nr>=0 && nr<len(groups) {
					out.WriteString(fmt.Sprintf("Removed group %d '%s'\n", nr, groups[nr].Name))
					groups=append(groups[:nr], groups[nr+1:]...)
				}
			}
			continue
		case "keep":
			if len(toks)>=2 {
				if nr,err:=strconv.Atoi(toks[1]); err==nil && nr>=0 && nr<len(groups) {
					var kept []NdxGroup
					for i,g:=range groups { if i!=nr { out.WriteString(fmt.Sprintf("Removed group %d '%s'\n", i, g.Name)) } else { kept=append(kept,g)} }
					groups=kept
				}
			}
			continue
		case "name":
			if len(toks)>=3 {
				if nr,err:=strconv.Atoi(toks[1]); err==nil && nr>=0 && nr<len(groups) { groups[nr].Name=strings.Join(toks[2:], " ") }
			}
			continue
		}
		// group expression evaluation (copy / atom / complement / combos)
		if newGroup, msgs, ok:=evalMakeNdxExpr(line, groups, maxAtom); ok {
			for _,m:=range msgs { out.WriteString(m+"\n") }
			groups=append(groups, newGroup)
			continue
		}
		// unhandled commands are ignored (original would do more specific things)
	}
	if save {
		outName:=getFileOpt(res,"make_ndx","o")
		content:=writeNdxFile(outName, groups)
		msg, blk:=writeOutput(outName, content, res.backupEnabled(), display)
		if blk!=nil { return &ExecResult{Out:out.String(), Block:blk, Exit:1} }
		return &ExecResult{Out:out.String(), ErrExtra:msg, Exit:0}
	}
	return &ExecResult{Out:out.String(), Exit:0}
}

func evalMakeNdxExpr(line string, groups []NdxGroup, maxAtom int) (NdxGroup, []string, bool) {
	// split by & or | keeping operator
	// token-based: terms separated by & / |
	var ops []string
	var terms []string
	// simple split on standalone & or |
	fields:=strings.Fields(line)
	var cur []string
	for _,f:=range fields {
		if f=="&" || f=="|" { terms=append(terms, strings.Join(cur," ")); ops=append(ops,f); cur=nil } else { cur=append(cur,f) }
	}
	terms=append(terms, strings.Join(cur," "))
	var msgs []string
	var result *NdxGroup
	for ti,term:=range terms {
		g, m, ok:=evalMakeNdxTerm(strings.TrimSpace(term), groups, maxAtom)
		if !ok { return NdxGroup{}, nil, false }
		msgs=append(msgs, m...)
		if result==nil {
			gg:=g; result=&gg
		} else {
			op:=ops[ti-1]
			var merged []int
			if op=="|" { merged=unionInts(result.Entries, g.Entries); msgs=append(msgs, fmt.Sprintf("Merged two groups with OR: %d %d -> %d", len(result.Entries), len(g.Entries), len(merged))) } else { merged=intersectInts(result.Entries, g.Entries); msgs=append(msgs, fmt.Sprintf("Merged two groups with AND: %d %d -> %d", len(result.Entries), len(g.Entries), len(merged))) }
			name:=result.Name+"_"+op+"_"+g.Name
			if strings.HasPrefix(g.Name, "a_") || strings.HasPrefix(result.Name,"a_") { // observed a-term naming uses underscore w/o op for a groups in OR case
				if op=="|" && strings.HasPrefix(result.Name,"a_") && strings.HasPrefix(g.Name,"a_") { name=result.Name+"_"+g.Name }
			}
			result=&NdxGroup{Name:name, Entries:merged}
		}
	}
	if result==nil { return NdxGroup{}, nil, false }
	return *result, msgs, true
}
func evalMakeNdxTerm(term string, groups []NdxGroup, maxAtom int) (NdxGroup, []string, bool) {
	term=strings.TrimSpace(term)
	if term=="" { return NdxGroup{},nil,false }
	// complement
	if strings.HasPrefix(term,"!") {
		inner:=strings.TrimSpace(term[1:])
		g,msgs,ok:=evalMakeNdxTerm(inner, groups, maxAtom); if !ok {return g,msgs,false}
		comp:=[]int{}; set:=map[int]bool{}; for _,e:=range g.Entries {set[e]=true}; for i:=1;i<=maxAtom;i++ { if !set[i] {comp=append(comp,i)}}
		msgs=append(msgs, fmt.Sprintf("Complemented group: %d atoms", len(comp)))
		return NdxGroup{Name:"!"+g.Name, Entries:comp}, msgs, true
	}
	toks:=strings.Fields(term)
	if toks[0]=="a" {
		if len(toks)<2 {return NdxGroup{},nil,false}
		// range a 1-2 or a 1 - 2
		rest:=strings.Join(toks[1:], " ")
		// name is a_ + tokens joined by '_'? Observed a 1 -> a_1, a 1-2 -> a_1-2
		nameParts:=strings.Join(toks[1:], "_"); // for range with spaces this may differ
		_ = rest
		// parse atoms: token can be 1, 1-2, 1,2 etc
		var entries []int; var msgs []string
		// handle range token
		for _,tok:=range toks[1:] {
			if strings.Contains(tok,"-") && tok!="-" {
				parts:=strings.Split(tok,"-"); if len(parts)==2 { a,_:=strconv.Atoi(parts[0]); b,_:=strconv.Atoi(parts[1]); cnt:=0; for v:=a; v<=b; v++ {entries=append(entries,v); cnt++}; msgs=append(msgs, fmt.Sprintf("Found %d atoms in range %s", cnt, tok)) }
			} else if tok=="-" {
				continue
			} else {
				if v,err:=strconv.Atoi(tok); err==nil { entries=append(entries,v) }
			}
		}
		// check range with separate '-' token: a 1 - 2
		if len(toks)==4 && toks[2]=="-" { a,_:=strconv.Atoi(toks[1]); b,_:=strconv.Atoi(toks[3]); entries=nil; for v:=a;v<=b;v++{entries=append(entries,v)}; msgs=[]string{fmt.Sprintf("Found %d atoms in range %d-%d", len(entries), a,b)}; nameParts=toks[1]+"-"+toks[3] }
		sort.Ints(entries)
		return NdxGroup{Name:"a_"+nameParts, Entries:uniqueInts(entries)}, msgs, true
	}
	// single group number
	if len(toks)==1 {
		if nr,err:=strconv.Atoi(toks[0]); err==nil && nr>=0 && nr<len(groups) {
			g:=groups[nr]
			return NdxGroup{Name:g.Name, Entries:append([]int{},g.Entries...)}, []string{fmt.Sprintf("Copied index group %d '%s'", nr, g.Name)}, true
		}
		// group name in quotes or bare matching
		name:=strings.Trim(toks[0], "\"")
		for i,g:=range groups { if g.Name==name { return NdxGroup{Name:g.Name, Entries:append([]int{},g.Entries...)}, []string{fmt.Sprintf("Copied index group %d '%s'", i, g.Name)}, true } }
	}
	return NdxGroup{},nil,false
}
func uniqueInts(in []int) []int { var out []int; seen:=map[int]bool{}; for _,v:=range in { if !seen[v]{seen[v]=true; out=append(out,v)}}; return out }
func unionInts(a,b []int) []int { set:=map[int]bool{}; for _,v:=range a{set[v]=true}; for _,v:=range b{set[v]=true}; var out []int; for v:=range set{out=append(out,v)}; sort.Ints(out); return out }
func intersectInts(a,b []int) []int { set:=map[int]bool{}; for _,v:=range a{set[v]=true}; var out []int; for _,v:=range b{ if set[v]{out=append(out,v)}}; sort.Ints(out); return uniqueInts(out) }
