		nameParts:=strings.Join(toks[1:], "_"); // for range with spaces this may differ
		_ = rest
		// parse atoms: token can be 1, 1-2, 1,2 etc
		var entries []int; var msgs []string
		// handle range token
		for _,tok:=range toks[1:] {
			if strings.Contains(tok,"-") && tok!="-" {
				parts:=strings.Split(tok,"-"); if len(parts)==2 { a,_:=strconv.Atoi(parts[0]); b,_:=strconv.Atoi(parts[1]); cnt:=0; for v:=a; v<=b; v++ {entries=append(entries,v); cnt++}; msgs=append(msgs, fmt.Sprintf("Found %d atoms in range %s", cnt, tok)) }
			} else if tok=="-" {
				continue
			} else {
				if v,err:=strconv.Atoi(tok); err==nil { entries=append(entries,v) }
			}
		}
		// check range with separate '-' token: a 1 - 2
		if len(toks)==4 && toks[2]=="-" { a,_:=strconv.Atoi(toks[1]); b,_:=strconv.Atoi(toks[3]); entries=nil; for v:=a;v<=b;v++{entries=append(entries,v)}; msgs=[]string{fmt.Sprintf("Found %d atoms in range %d-%d", len(entries), a,b)}; nameParts=toks[1]+"-"+toks[3] }
		sort.Ints(entries)
