{"command":"cat > /workspace/trjconv.go << 'GO'
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func groupListStderr(groups []NdxGroup) string {
	var b strings.Builder
	for i,g:=range groups {
		b.WriteString(fmt.Sprintf("Group %5d (%15s) has %5d elements\n", i, g.Name, len(g.Entries)))
	}
	return b.String()
}
func selectGroupByInput(input string, groups []NdxGroup) (int,bool) {
	input=strings.TrimSpace(input)
	if n,err:=strconv.Atoi(input); err==nil {
		if n>=0 && n<len(groups) { return n,true }
		return -1,false
	}
	name:=strings.Trim(input, "\"")
	// exact
	for i,g:=range groups { if g.Name==name { return i,true } }
	// prefix
	var matches []int
	for i,g:=range groups { if strings.HasPrefix(g.Name, name) { matches=append(matches,i)} }
	if len(matches)==1 { return matches[0],true }
	// substring
	matches=nil
	for i,g:=range groups { if strings.Contains(g.Name, name) { matches=append(matches,i)} }
	if len(matches)==1 { return matches[0],true }
	return -1,false
}

func handleTrjconv(res *ParseResult, display string) *ExecResult {
	if !res.isSet("f") || !res.isSet("s") || !res.isSet("n") { return nil }
	fname:=getFileOpt(res,"trjconv","f"); sname:=getFileOpt(res,"trjconv","s"); oname:=getFileOpt(res,"trjconv","o")
	if fileExtOf(fname)!=".gro" || fileExtOf(sname)!=".gro" || fileExtOf(oname)!=".gro" { return nil }
	// only default transformations
	if res.boolVal("center", false) { return nil }
	if v:=getEnumOpt(res,"trjconv","fit"); v!="" && v!="none" { return nil }
	if v:=getEnumOpt(res,"trjconv","pbc"); v!="" && v!="none" { return nil }
	groups,err:=parseNdxFile(getFileOpt(res,"trjconv","n")); if err!=nil { return nil }
	var out strings.Builder; var er strings.Builder
	out.WriteString(noteFor("trjconv"))
	out.WriteString("Select group for output\n")
	er.WriteString("Will write gro: Coordinate file in Gromos-87 format\n")
	er.WriteString(groupListStderr(groups))
	reader:=bufio.NewReader(os.Stdin)
	var selected int; haveSel:=false
	for !haveSel {
		er.WriteString("Select a group: ")
		line, rerr:=reader.ReadString('\n')
		if rerr!=nil && strings.TrimSpace(line)=="" {
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/topology/index.cpp", Line:874, Heading:"Fatal error:", Body:"Cannot read from input\n"}
			return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1}
		}
		idx,ok:=selectGroupByInput(line, groups)
		if !ok {
			out.WriteString(fmt.Sprintf("Error: No such group '%s'\n", strings.TrimSpace(line)))
			continue
		}
		selected=idx; haveSel=true
		out.WriteString(fmt.Sprintf("Selected %d: '%s'\n", selected, groups[selected].Name))
	}
	frames,_,perr:=parseGroFile(fname); if perr!=nil { return nil }
	sel:=groups[selected]
	// build output and messages
	var fileOut strings.Builder
	if len(frames)>0 {
		er.WriteString(fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n", frames[0].Title, frames[0].NAtoms))
	}
	backupMsg:=""
	for i,fr:=range frames {
		er.WriteString(fmt.Sprintf("\nReading frame %7d time %8.3f   \n", i, 0.0))
		if i==0 { er.WriteString(fmt.Sprintf("Precision of %s is 0.001 (nm)\n", fname)) }
		// write frame
		fileOut.WriteString(fr.Title+"\n")
		// selected lines: entries are 1-based atom numbers in original frame; fr.Lines indexed by atom position (atomnr-1 if lines correspond)
		fileOut.WriteString(fmt.Sprintf("%5d\n", len(sel.Entries)))
		for _,e:=range sel.Entries { if e-1>=0 && e-1<len(fr.Lines) { fileOut.WriteString(fr.Lines[e-1]+"\n") } }
		if len(fr.Box)>0 {
			parts:=[]string{}
			for _,v:=range fr.Box { parts=append(parts, fmt.Sprintf("%10.5f", v)) }
			fileOut.WriteString(strings.Join(parts,"")+"\n")
		}
		if i==0 {
			// output file is first written here; backup message happens in original between Precision and Last frame
			msg, blk:=writeOutput(oname, "", res.backupEnabled(), display); _=msg; _=blk
			// we will write full content later; to capture backup msg at right position, remove placeholder and handle below
			// Actually writeOutput above created/truncated empty file; restore content later.
			// Capture backup by checking before writing: simpler: we already performed backup via writeOutput with empty content.
			// Save msg:
			backupMsg=msg
			if blk!=nil { return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1} }
			er.WriteString("\n"+strings.TrimPrefix(backupMsg, "\n"))
			if backupMsg!="" && !strings.HasSuffix(backupMsg,"\n") { er.WriteString("\n") }
			// backupMsg already ends with newline; the code above added a blank line before it as original: Actually original backup line is preceded by a blank line (after Precision line, blank, Back Off, blank?) Captured: "Precision...\n\nBack Off!...\n\nLast..." So:
			// Our er currently: ...Precision\n + "\n"+backup(without leading \n?) writeOutput backupMsg starts with \n, TrimPrefix removes it, we printed \n+msg -> that gives blank then Back. Need ensure ends with \n then blank before Last handled below.
		}
		er.WriteString(fmt.Sprintf("\nLast frame %10d time %8.3f   \n", i, 0.0))
		er.WriteString(fmt.Sprintf(" ->  frame %7d time %8.3f      \n", i, 0.0))
	}
	if len(frames)>0 {
		er.WriteString(fmt.Sprintf("Last written: frame %7d time %8.3f\n", len(frames)-1, 0.0))
		er.WriteString("\n")
	}
	// write actual content (backup already handled if file existed; if not, write now)
	// If backup happened, file currently exists as empty placeholder; overwrite without backup.
	if backupMsg!="" {
		// file was backed up and empty file created; write content directly
		// use os write
		writeOutputNoBackup(oname, fileOut.String())
	} else {
		// check if file existed before (it would have been placeholder only if frames>0; if no frames, write with backup)
		if len(frames)==0 {
			msg,blk:=writeOutput(oname, fileOut.String(), res.backupEnabled(), display); if blk!=nil { return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1} }; _=msg
		} else {
			// first write already truncated/created file (no backup msg means it didn't exist), write content
			writeOutputNoBackup(oname, fileOut.String())
		}
	}
	return &ExecResult{Out:out.String(), ErrExtra:er.String(), Exit:0}
}
func writeOutputNoBackup(path, content string) {
	// direct write
	_ = writeFileDirect(path, content)
}
