{"command":"rm -f angdist.xvg; ls *.xvg 2>/dev/null; cat > /workspace/angle.go << 'GO'
package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strings"
)

func handleAngle(res *ParseResult, display string) *ExecResult {
	if !res.isSet("f") || !res.isSet("n") { return nil }
	fname:=getFileOpt(res,"angle","f"); nname:=getFileOpt(res,"angle","n")
	if fileExtOf(fname)!=".gro" { return nil }
	groups,err:=parseNdxFile(nname); if err!=nil { return nil }
	typ:=getEnumOpt(res,"angle","type")
	var er strings.Builder; var out strings.Builder
	er.WriteString(groupListStderr(groups))
	reader:=bufio.NewReader(os.Stdin)
	var selIdx int; have:=false
	for !have {
		er.WriteString("Select a group: ")
		line,rerr:=reader.ReadString('\n')
		if rerr!=nil && strings.TrimSpace(line)=="" {
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/topology/index.cpp", Line:874, Heading:"Fatal error:", Body:"Cannot read from input\n"}
			return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1}
		}
		idx,ok:=selectGroupByInput(line, groups)
		if !ok { out.WriteString(fmt.Sprintf("Error: No such group '%s'\n", strings.TrimSpace(line))); continue }
		selIdx=idx; have=true; out.WriteString(fmt.Sprintf("Selected %d: '%s'\n", selIdx, groups[selIdx].Name))
	}
	sel:=groups[selIdx]
	// validate multiplicity
	if typ=="angle" && len(sel.Entries)%3!=0 {
		blk:=&ErrorBlock{Program:display, Source:"src/gromacs/gmxana/gmx_angle.cpp", Line:244, Heading:"Fatal error:", Body:"number of index elements not multiple of 3, these can not be angle triplets\n"}
		return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1}
	}
	if typ=="dihedral" && len(sel.Entries)%4!=0 {
		blk:=&ErrorBlock{Program:display, Source:"src/gromacs/gmxana/gmx_angle.cpp", Line:244, Heading:"Fatal error:", Body:"number of index elements not multiple of 4, these can not be dihedral\nquadruplets\n"}
		return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1}
	}
	if typ!="angle" { return nil } // dihedral not implemented
	frames,_,perr:=parseGroFile(fname); if perr!=nil { return nil }
	// reading frames message (with \r progress as legacy reader)
	if len(frames)>0 { er.WriteString(fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n", frames[0].Title, frames[0].NAtoms)) }
	var angles []float64
	var timeAngles [][]float64 // per frame list (for -ov)
	for fi,fr:=range frames {
		er.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", fi, 0.0))
		// parse atom positions
		pos:=map[int][3]float64{}
		for _,line:= range fr.Lines { if a,ok:=parseGroAtom(line); ok { pos[a.AtomNr]=[3]float64{a.X,a.Y,a.Z}}}
		var frameAngles []float64
		for t:=0;t+2<len(sel.Entries);t+=3 {
			a1:=sel.Entries[t]; a2:=sel.Entries[t+1]; a3:=sel.Entries[t+2]
			p1,ok1:=pos[a1]; p2,ok2:=pos[a2]; p3,ok3:=pos[a3]; if !ok1||!ok2||!ok3 { continue }
			// wrap coordinates into box if present
			wrap:=func(p [3]float64) [3]float64 { if len(fr.Box)>=3 { for i:=0;i<3;i++ { if fr.Box[i]>0 { p[i]=p[i]-math.Floor(p[i]/fr.Box[i])*fr.Box[i] } } }; return p }
			p1=wrap(p1); p2=wrap(p2); p3=wrap(p3)
			var v1,v2 [3]float64
			for i:=0;i<3;i++ { v1[i]=p1[i]-p2[i]; v2[i]=p3[i]-p2[i]; // minimum image
				if len(fr.Box)>=3 && fr.Box[i]>0 { v1[i]-=math.Round(v1[i]/fr.Box[i])*fr.Box[i]; v2[i]-=math.Round(v2[i]/fr.Box[i])*fr.Box[i] } }
			dot:=v1[0]*v2[0]+v1[1]*v2[1]+v1[2]*v2[2]
			n1:=math.Sqrt(v1[0]*v1[0]+v1[1]*v1[1]+v1[2]*v1[2]); n2:=math.Sqrt(v2[0]*v2[0]+v2[1]*v2[1]+v2[2]*v2[2])
			cosang:=dot/(n1*n2); if cosang>1 {cosang=1}; if cosang<-1 {cosang=-1}
			ang:=math.Acos(cosang)*180/math.Pi
			if ang>=179.999999 { ang=-180 }
			frameAngles=append(frameAngles, ang); angles=append(angles, ang)
		}
		timeAngles=append(timeAngles, frameAngles)
	}
	if len(frames)>0 { er.WriteString(fmt.Sprintf("\rLast frame %10d time %8.3f   \n", len(frames)-1, 0.0)) }
	if len(angles)==0 { return &ExecResult{Out:out.String(), ErrExtra:er.String(), Exit:0} }
	avg:=0.0; for _,a:=range angles {avg+=a}; avg/=float64(len(angles))
	// histogram
	binw:=getFloat(res,"angle","binwidth"); if binw==0 {binw=1}
	normalize:=res.boolVal("normalize", true)
	counts:=map[int]int{}
	for _,a:=range angles { idx:=int(math.Round(a/binw)); counts[idx]++ }
	minIdx,maxIdx:=0,0; first:=true; for idx:=range counts { if first||idx<minIdx {minIdx=idx}; if first||idx>maxIdx {maxIdx=idx}; first=false }
	fromIdx:=minIdx-1; toIdx:=maxIdx+1
	fromVal:=float64(fromIdx)*binw; toVal:=float64(toIdx)*binw
	out.WriteString(fmt.Sprintf("Found points in the range from %s to %s (max 180)\n", formatG(fromVal), formatG(toVal)))
	out.WriteString(fmt.Sprintf(" < angle >  = %s\n", formatG(avg)))
	// angdist output (default -od file, always written)
	odName:=getFileOpt(res,"angle","od")
	var od strings.Builder
	if xv:=getEnumOpt(res,"angle","xvg"); xv!="none" {
		od.WriteString(xvgFileHeader(display, xv))
		od.WriteString(fmt.Sprintf("@    title \"Angle Distribution: %s\"\n", sel.Name))
		od.WriteString("@    xaxis  label \"Degrees\"\n")
		od.WriteString("@    yaxis  label \"\"\n")
		if xv=="xmgr" { od.WriteString("@TYPE nxy\n") } else { od.WriteString("@TYPE xy\n") }
		od.WriteString(fmt.Sprintf("@    subtitle \"average angle: %s\\So\\N\"\n", formatG(avg)))
	}
	// special -180-only edge: original writes no data rows in that case
	onlyMinus180:=true; for _,a:=range angles { if a!=-180 {onlyMinus180=false} }
	if !onlyMinus180 {
		for idx:=fromIdx; idx<=toIdx; idx++ {
			var y float64
			if normalize { y=float64(counts[idx])/float64(len(angles)) } else { y=float64(counts[idx]) }
			// For binwidth !=1, normalized histogram in original is divided by binwidth? Keep simple for binwidth=1 case
			od.WriteString(fmt.Sprintf("%s %s\n", padField(formatG(float64(idx)*binw),10), padField(fmt.Sprintf("%.6f", y),11)))
		}
	}
	backupMsgs:=""
	if msg,blk:=writeOutput(odName, od.String(), res.backupEnabled(), display); blk!=nil { return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1} } else { backupMsgs+=msg }
	// -ov average over time
	if res.isSet("ov") {
		ovName:=getFileOpt(res,"angle","ov")
		var ov strings.Builder
		if xv:=getEnumOpt(res,"angle","xvg"); xv!="none" {
			ov.WriteString(xvgFileHeader(display, xv))
			ov.WriteString(fmt.Sprintf("@    title \"Average Angle: %s\"\n", sel.Name))
			ov.WriteString("@    xaxis  label \"Time (ps)\"\n")
			ov.WriteString("@    yaxis  label \"Angle (degrees)\"\n")
			if xv=="xmgr" { ov.WriteString("@TYPE nxy\n") } else { ov.WriteString("@TYPE xy\n") }
		}
		for fi,fa:=range timeAngles { _=fi; if len(fa)>0 { av:=0.0; for _,a:=range fa {av+=a}; av/=float64(len(fa)); ov.WriteString(fmt.Sprintf("%10.5f    %s\n", 0.0, formatG(av))) } }
		if msg,blk:=writeOutput(ovName, ov.String(), res.backupEnabled(), display); blk!=nil { return &ExecResult{Out:out.String(), ErrExtra:er.String(), Block:blk, Exit:1} } else { backupMsgs+=msg }
	}
	// original creates other output files as empty? -of etc only if set, not handled
	return &ExecResult{Out:out.String(), ErrExtra:er.String()+backupMsgs, Exit:0}
}
GO
