package main

import (
	"math"
	"strconv"
	"strings"
)

type FrameAtom struct {
	AtomNr int
	ResNr int
	ResName string
	AtomName string
	Pos [3]float64
	FrameIdx int // 0-based in frame
}
func atomsOfFrame(fr GroFrame) []FrameAtom {
	var atoms []FrameAtom
	for i,line:=range fr.Lines {
		if a,ok:=parseGroAtom(line); ok {
			atoms=append(atoms, FrameAtom{AtomNr:a.AtomNr, ResNr:a.ResNr, ResName:a.ResName, AtomName:a.AtomName, Pos:[3]float64{a.X,a.Y,a.Z}, FrameIdx:i})
		}
	}
	return atoms
}

type selParser struct {
	toks []selToken
	pos int
	atoms []FrameAtom
	groups []NdxGroup
	box []float64
}
func (p *selParser) peek() (selToken,bool) { if p.pos<len(p.toks) { return p.toks[p.pos],true }; return selToken{},false }
func (p *selParser) next() (selToken,bool) { t,ok:=p.peek(); if ok {p.pos++}; return t,ok }
func (p *selParser) accept(word string) bool { if t,ok:=p.peek(); ok && t.Kind=="id" && strings.EqualFold(t.Text,word) {p.pos++; return true}; return false }

func evalSelection(sel string, atoms []FrameAtom, groups []NdxGroup, box []float64) (map[int]bool, bool) {
	toks,bad:=tokenizeSelection(sel)
	if bad!="" { return nil,false }
	if len(toks)==0 { return nil,false }
	p:=&selParser{toks:toks, atoms:atoms, groups:groups, box:box}
	set,ok:=p.parseOr()
	if !ok { return nil,false }
	if p.pos!=len(p.toks) { return nil,false }
	return set, true
}
func allSet(atoms []FrameAtom) map[int]bool { s:=map[int]bool{}; for _,a:=range atoms {s[a.FrameIdx]=true}; return s }
func (p *selParser) parseOr() (map[int]bool,bool) {
	left,ok:=p.parseAnd(); if !ok {return nil,false}
	for { if p.accept("or") { right,ok:=p.parseAnd(); if !ok {return nil,false}; for k:=range right {left[k]=true} } else {break} }
	return left,true
}
func (p *selParser) parseAnd() (map[int]bool,bool) {
	left,ok:=p.parseUnary(); if !ok {return nil,false}
	for { if p.accept("and") { right,ok:=p.parseUnary(); if !ok {return nil,false}; out:=map[int]bool{}; for k:=range left { if right[k] {out[k]=true} }; left=out } else {break} }
	return left,true
}
func (p *selParser) parseUnary() (map[int]bool,bool) {
	if p.accept("not") { inner,ok:=p.parseUnary(); if !ok {return nil,false}; out:=map[int]bool{}; for _,a:=range p.atoms { if !inner[a.FrameIdx] {out[a.FrameIdx]=true} }; return out,true }
	return p.parsePrimary()
}
func (p *selParser) parsePrimary() (map[int]bool,bool) {
	t,ok:=p.next(); if !ok {return nil,false}
	if t.Text=="(" { inner,ok:=p.parseOr(); if !ok {return nil,false}; if nt,ok:=p.next(); !ok||nt.Text!=")" {return nil,false}; return inner,true }
	if t.Kind!="id" { return nil,false }
	low:=strings.ToLower(t.Text)
	switch low {
	case "all": return allSet(p.atoms),true
	case "none": return map[int]bool{},true
	case "atomnr","resnr","resid","resindex","molindex","mol","x","y","z","charge","mass","beta","betafactor","occupancy":
		// Check for comparison operator next
		if nt,ok:=p.peek(); ok && nt.Kind=="op" {
			return p.parseNumericComparison(low)
		}
		if low=="atomnr" || low=="resnr" || low=="resid" || low=="resindex" {
			// parse list of numbers / ranges
			set:=map[int]bool{}
			// collect numbers
			for {
				nt,ok:=p.peek(); if !ok {break}
				if nt.Kind=="num" {
					p.next(); start,_:=strconv.Atoi(nt.Text)
					if p.accept("to") {
						if et,ok:=p.next(); ok && et.Kind=="num" { end,_:=strconv.Atoi(et.Text); for _,a:=range p.atoms { v:=propValue(a,low); if v>=float64(start) && v<=float64(end) {set[a.FrameIdx]=true} }; continue }
						return nil,false
					}
					for _,a:=range p.atoms { if int(propValue(a,low))==start {set[a.FrameIdx]=true} }
					continue
				}
				break
			}
			return set,true
		}
		return nil,false
	case "within":
		// within <num> of <primary>
		nt,ok:=p.next(); if !ok||nt.Kind!="num" {return nil,false}; dist,_:=strconv.ParseFloat(nt.Text,64)
		if !p.accept("of") {return nil,false}
		inner,ok:=p.parsePrimary(); if !ok {return nil,false}
		out:=map[int]bool{}
		var centers [][3]float64; for _,a:=range p.atoms { if inner[a.FrameIdx] {centers=append(centers,a.Pos)}}
		for _,a:=range p.atoms { for _,c:=range centers { if distPBC(a.Pos,c,p.box)<=dist { out[a.FrameIdx]=true; break } } }
		return out,true
	case "same":
		// same residue as <expr>
		if !p.accept("residue") {return nil,false}; if !p.accept("as") {return nil,false}
		inner,ok:=p.parseOr(); if !ok {return nil,false}
		resSet:=map[int]bool{}; for _,a:=range p.atoms { if inner[a.FrameIdx] {resSet[a.ResNr]=true} }
		out:=map[int]bool{}; for _,a:=range p.atoms { if resSet[a.ResNr] {out[a.FrameIdx]=true} }; return out,true
	}
	// group name identifier
	// try exact/prefix/substring groups
	if idx,ok:=selectGroupByInput(t.Text, p.groups); ok { _=idx; g:=p.groups[idx]; out:=map[int]bool{}; set:=map[int]bool{}; for _,e:=range g.Entries {set[e]=true}; for _,a:=range p.atoms { if set[a.AtomNr] {out[a.FrameIdx]=true} }; return out,true }
	return nil,false
}
func propValue(a FrameAtom, prop string) float64 {
	switch prop {
	case "atomnr": return float64(a.AtomNr)
	case "resnr","resid": return float64(a.ResNr)
	case "resindex": return float64(a.ResNr)
	case "x": return a.Pos[0]
	case "y": return a.Pos[1]
	case "z": return a.Pos[2]
	default: return 0
	}
}
func (p *selParser) parseNumericComparison(prop string) (map[int]bool,bool) {
	// current peek is operator
	opTok,ok:=p.next(); if !ok {return nil,false}
	op:=opTok.Text
	// rhs number (allow unary minus as separate op token '-')
	var sign float64=1
	if nt,ok:=p.peek(); ok && (nt.Text=="-"||nt.Text=="+") { p.next(); if nt.Text=="-" {sign=-1} }
	nt,ok:=p.next(); if !ok||nt.Kind!="num" {return nil,false}
	rhs,_:=strconv.ParseFloat(nt.Text,64); rhs*=sign
	out:=map[int]bool{}
	for _,a:=range p.atoms { v:=propValue(a,prop); var res bool; switch op { case "<": res=v<rhs; case "<=": res=v<=rhs; case ">": res=v>rhs; case ">=": res=v>=rhs; case "=", "==": res=v==rhs; case "!=": res=v!=rhs }
		if res {out[a.FrameIdx]=true} }
	return out,true
}
func distPBC(a,b [3]float64, box []float64) float64 {
	var sq float64
	for i:=0;i<3;i++ { d:=a[i]-b[i]; if len(box)>=3 && box[i]>0 { d-=math.Round(d/box[i])*box[i] }; sq+=d*d }
	return math.Sqrt(sq)
}
