func handleGyrateTool(res *ParseResult, display string) *ExecResult {
	if res.isSet("s") { return nil }
	fname:=getFileOpt(res,"gyrate","f"); if fileExtOf(fname)!=".gro" {return nil}
	selVals:=res.values("sel"); if len(selVals)!=1 {return nil}
	sel:=selVals[0]
	if selectionRequiresTopology(sel) { return &ExecResult{Block:initTopologyError(display), Exit:1} }
	frames,_,err:=parseGroFile(fname); if err!=nil {return nil}
	var groups []NdxGroup
	if res.isSet("n") { groups,_=parseNdxFile(getFileOpt(res,"gyrate","n")) }
	var outRows strings.Builder
	backupMsgs:=""
	for _,fr:=range frames {
		atoms:=atomsOfFrame(fr)
		set,ok:=evalSelection(sel, atoms, groups, fr.Box); if !ok {return nil}
		var pts [][3]float64; for _,a:=range atoms { if set[a.FrameIdx] {pts=append(pts,a.Pos)} }
		if len(pts)==0 { continue }
		var com [3]float64; for _,pt:=range pts { for i:=0;i<3;i++ {com[i]+=pt[i]}}
		for i:=0;i<3;i++ {com[i]/=float64(len(pts))}
		var sumSq, sumX, sumY, sumZ float64
		for _,pt:=range pts { dx:=pt[0]-com[0]; dy:=pt[1]-com[1]; dz:=pt[2]-com[2]; sumSq+=dx*dx+dy*dy+dz*dz; sumX+=dy*dy+dz*dz; sumY+=dx*dx+dz*dz; sumZ+=dx*dx+dy*dy }
		n:=float64(len(pts))
		outRows.WriteString(fmt.Sprintf("%11.3f %.6f %.6f %.6f %.6f\n", 0.0, math.Sqrt(sumSq/n), math.Sqrt(sumX/n), math.Sqrt(sumY/n), math.Sqrt(sumZ/n)))
	}
	oname:=getFileOpt(res,"gyrate","o")
	var file strings.Builder
	if xv:=getEnumOpt(res,"gyrate","xvg"); xv!="none" {
		file.WriteString(xvgFileHeader(display, xv))
		file.WriteString("@    title \"Radius of gyration (total and around axes)\"\n")
		file.WriteString("@    xaxis  label \"Time (ps)\"\n")
		file.WriteString("@    yaxis  label \"Radius (nm)\"\n")
		if xv=="xmgr" { file.WriteString("@TYPE nxy\n") } else { file.WriteString("@TYPE xy\n") }
		file.WriteString(xvgViewLegend(display, []string{"Rg","Rg\\sX\\N","Rg\\sY\\N","Rg\\sZ\\N"}))
		// The original file uses forward slashes in these legends (Rg/sX/N) - adjust above strings?
	}
	content:=file.String()+outRows.String()
	// Fix legend strings to forward slash as observed
	content=strings.ReplaceAll(content, "Rg\\sX\\N", "Rg/sX/N"); content=strings.ReplaceAll(content, "Rg\\sY\\N", "Rg/sY/N"); content=strings.ReplaceAll(content, "Rg\\sZ\\N", "Rg/sZ/N")
	if msg,blk:=writeOutput(oname, content, res.backupEnabled(), display); blk!=nil {return &ExecResult{Block:blk,Exit:1}} else { backupMsgs=msg }
	return &ExecResult{ErrExtra:frameSummaryGro(frames)+backupMsgs, Exit:0}
}

func handleRDFTool(res *ParseResult, display string) *ExecResult {
	if res.isSet("s") { return nil }
	fname:=getFileOpt(res,"rdf","f"); if fileExtOf(fname)!=".gro" {return nil}
	refVals:=res.values("ref"); selVals:=res.values("sel")
	if len(refVals)!=1 || len(selVals)==0 {return nil}
	for _,s:=range append(append([]string{},refVals...), selVals...) { if selectionRequiresTopology(s) { return &ExecResult{Block:initTopologyError(display), Exit:1} } }
	frames,_,err:=parseGroFile(fname); if err!=nil || len(frames)==0 {return nil}
	var groups []NdxGroup
	if res.isSet("n") { groups,_=parseNdxFile(getFileOpt(res,"rdf","n")) }
	binw:=getFloat(res,"rdf","bin"); if binw==0 {binw=0.002}
	rmaxOpt:=getFloat(res,"rdf","rmax")
	pbc:=res.boolVal("pbc", true)
	norm:=getEnumOpt(res,"rdf","norm")
	if norm!="" && norm!="rdf" {return nil}
	if res.boolVal("xy", false) {return nil}
	// determine rmax
	var box0 []float64; if len(frames[0].Box)>=3 {box0=frames[0].Box}
	var rmax float64
	if rmaxOpt>0 { rmax=rmaxOpt } else if pbc && len(box0)>=3 { rmax=0.5*math.Min(box0[0], math.Min(box0[1],box0[2])) } else {return nil}
	nbins:=int(math.Ceil(rmax/binw))
	if nbins<=0 {return nil}
	counts:=make([][]int, len(selVals)); for i:=range counts {counts[i]=make([]int,nbins)}
	var sumNref, sumVol float64; sumNsel:=make([]float64,len(selVals))
	for _,fr:=range frames {
		atoms:=atomsOfFrame(fr)
		refSet,ok:=evalSelection(refVals[0], atoms, groups, fr.Box); if !ok {return nil}
		var refPts [][3]float64; var refIdx []int
		for _,a:=range atoms { if refSet[a.FrameIdx] {refPts=append(refPts,a.Pos); refIdx=append(refIdx,a.FrameIdx)} }
		sumNref+=float64(len(refPts))
		vol:=1.0; if len(fr.Box)>=3 {vol=fr.Box[0]*fr.Box[1]*fr.Box[2]}; sumVol+=vol
		for si,sv:=range selVals {
			selSet,ok:=evalSelection(sv, atoms, groups, fr.Box); if !ok {return nil}
			var selPts [][3]float64; var selIdx []int; for _,a:=range atoms { if selSet[a.FrameIdx] {selPts=append(selPts,a.Pos); selIdx=append(selIdx,a.FrameIdx)} }
			sumNsel[si]+=float64(len(selPts))
			for ri,rp:=range refPts { for sj,sp:=range selPts { if refIdx[ri]==selIdx[sj] {continue}
				d:=distPBC(rp,sp,fr.Box); if !pbc { var sq float64; for i:=0;i<3;i++ {dd:=rp[i]-sp[i]; sq+=dd*dd}; d=math.Sqrt(sq) }
				if d>=rmax {continue}; bin:=int(math.Round(d/binw)); if bin>=0 && bin<nbins {counts[si][bin]++}
			}}
		}
	}
	nf:=float64(len(frames)); avgNref:=sumNref/nf; avgVol:=sumVol/nf
	oname:=getFileOpt(res,"rdf","o")
	var file strings.Builder
	xv:=getEnumOpt(res,"rdf","xvg")
	if xv!="none" {
		file.WriteString(xvgFileHeader(display, xv))
		file.WriteString("@    title \"Radial distribution\"\n")
		file.WriteString("@    xaxis  label \"r (nm)\"\n")
		file.WriteString("@    yaxis  label \"g(r)\"\n")
		if xv=="xmgr" { file.WriteString("@TYPE nxy\n") } else { file.WriteString("@TYPE xy\n") }
		file.WriteString(fmt.Sprintf("@ subtitle \"reference %s\"\n", refVals[0]))
		file.WriteString(xvgViewLegend(display, selVals))
	}
	for b:=0;b<nbins;b++ {
		r:=float64(b)*binw
		file.WriteString(fmt.Sprintf("%11.6f", r))
		low:=r-binw/2; if low<0 {low=0}; shell:=4*math.Pi/3*(math.Pow(r+binw/2,3)-math.Pow(low,3))
		for si:=range selVals {
			var y float64
			avgCount:=float64(counts[si][b])/nf; avgNsel:=sumNsel[si]/nf
			if shell>0 && avgNref>0 && avgNsel>0 && avgVol>0 { y=avgCount/(avgNref*(avgNsel/avgVol)*shell) }
			file.WriteString(fmt.Sprintf(" %11.6f", y))
		}
		file.WriteString("\n")
	}
	backupMsgs:=""
	if msg,blk:=writeOutput(oname, file.String(), res.backupEnabled(), display); blk!=nil {return &ExecResult{Block:blk,Exit:1}} else {backupMsgs+=msg}
	// -cn cumulative
	if res.isSet("cn") {
		cnName:=getFileOpt(res,"rdf","cn")
		var cn strings.Builder
		if xv!="none" {
			cn.WriteString(xvgFileHeader(display, xv))
			cn.WriteString("@    title \"Cumulative number\"\n")
			// x/y labels approximated from original (not yet probed); keep minimal header copying RDF? We'll generate same axes as rdf?
			cn.WriteString("@    xaxis  label \"r (nm)\"\n")
			cn.WriteString("@    yaxis  label \"N\"\n")
			if xv=="xmgr" { cn.WriteString("@TYPE nxy\n") } else { cn.WriteString("@TYPE xy\n") }
			cn.WriteString(xvgViewLegend(display, selVals))
		}
		cum:=make([]float64,len(selVals))
		for b:=0;b<nbins;b++ {
			r:=float64(b)*binw; cn.WriteString(fmt.Sprintf("%11.6f",r))
			for si:=range selVals { if avgNref>0 {cum[si]+=float64(counts[si][b])/nf/avgNref}; cn.WriteString(fmt.Sprintf(" %11.6f",cum[si])) }
			cn.WriteString("\n")
		}
		if msg,blk:=writeOutput(cnName, cn.String(), res.backupEnabled(), display); blk!=nil {return &ExecResult{Block:blk,Exit:1}} else {backupMsgs+=msg}
	}
	return &ExecResult{ErrExtra:frameSummaryGro(frames)+backupMsgs, Exit:0}
}
