func xvgViewLegend(display string, legends []string) string {
	var b strings.Builder
	b.WriteString("@ view 0.15, 0.15, 0.75, 0.85\n")
	b.WriteString("@ legend on\n")
	b.WriteString("@ legend box on\n")
	b.WriteString("@ legend loctype view\n")
	b.WriteString("@ legend 0.78, 0.8\n")
	b.WriteString("@ legend length 2\n")
	for i,l:=range legends { b.WriteString(fmt.Sprintf("@ s%d legend \"%s\"\n", i,l)) }
	return b.String()
}

func handleGyrateTool(res *ParseResult, display string) *ExecResult {
	if res.isSet("s") { return nil }
	fname:=getFileOpt(res,"gyrate","f"); if fileExtOf(fname)!=".gro" {return nil}
	selVals:=res.values("sel"); if len(selVals)!=1 {return nil}
	sel:=selVals[0]
	if selectionRequiresTopology(sel) { return &ExecResult{Block:initTopologyError(display), Exit:1} }
	frames,_,err:=parseGroFile(fname); if err!=nil {return nil}
	var groups []NdxGroup
	if res.isSet("n") { groups,_=parseNdxFile(getFileOpt(res,"gyrate","n")) }
	var outRows strings.Builder
	backupMsgs:=""
	for _,fr:=range frames {
		atoms:=atomsOfFrame(fr)
		set,ok:=evalSelection(sel, atoms, groups, fr.Box); if !ok {return nil}
		var pts [][3]float64; for _,a:=range atoms { if set[a.FrameIdx] {pts=append(pts,a.Pos)} }
		if len(pts)==0 { continue }
		var com [3]float64; for _,pt:=range pts { for i:=0;i<3;i++ {com[i]+=pt[i]}}
		for i:=0;i<3;i++ {com[i]/=float64(len(pts))}
		var sumSq, sumX, sumY, sumZ float64
		for _,pt:=range pts { dx:=pt[0]-com[0]; dy:=pt[1]-com[1]; dz:=pt[2]-com[2]; sumSq+=dx*dx+dy*dy+dz*dz; sumX+=dy*dy+dz*dz; sumY+=dx*dx+dz*dz; sumZ+=dx*dx+dy*dy }
		n:=float64(len(pts))
		outRows.WriteString(fmt.Sprintf("%11.3f %.6f %.6f %.6f %.6f\n", 0.0, math.Sqrt(sumSq/n), math.Sqrt(sumX/n), math.Sqrt(sumY/n), math.Sqrt(sumZ/n)))
	}
	oname:=getFileOpt(res,"gyrate","o")
	var file strings.Builder
	if xv:=getEnumOpt(res,"gyrate","xvg"); xv!="none" {
		file.WriteString(xvgFileHeader(display, xv))
		file.WriteString("@    title \"Radius of gyration (total and around axes)\"\n")
		file.WriteString("@    xaxis  label \"Time (ps)\"\n")
		file.WriteString("@    yaxis  label \"Radius (nm)\"\n")
		if xv=="xmgr" { file.WriteString("@TYPE nxy\n") } else { file.WriteString("@TYPE xy\n") }
		file.WriteString(xvgViewLegend(display, []string{"Rg","Rg\\sX\\N","Rg\\sY\\N","Rg\\sZ\\N"}))
		// The original file uses forward slashes in these legends (Rg/sX/N) - adjust above strings?
	}
	content:=file.String()+outRows.String()
	// Fix legend strings to forward slash as observed
	content=strings.ReplaceAll(content, "Rg\\sX\\N", "Rg/sX/N"); content=strings.ReplaceAll(content, "Rg\\sY\\N", "Rg/sY/N"); content=strings.ReplaceAll(content, "Rg\\sZ\\N", "Rg/sZ/N")
	if msg,blk:=writeOutput(oname, content, res.backupEnabled(), display); blk!=nil {return &ExecResult{Block:blk,Exit:1}} else { backupMsgs=msg }
	return &ExecResult{ErrExtra:frameSummaryGro(frames)+backupMsgs, Exit:0}
}

func handleRDFTool(res *ParseResult, display string) *ExecResult {
