func handleDistanceTool(res *ParseResult, display string) *ExecResult {
	if res.isSet("s") { return nil }
	fname:=getFileOpt(res,"distance","f"); if fileExtOf(fname)!=".gro" {return nil}
	selVals:=splitSelections(res.values("select")); if len(selVals)==0 {return nil}
