	var groups []NdxGroup
	if res.isSet("n") { groups,_=parseNdxFile(getFileOpt(res,"distance","n")) }
	pbc:=res.boolVal("pbc", true)
	// check even positions on first frame in order
	atoms0:=atomsOfFrame(frames[0])
