			return &ExecResult{ErrExtra:pre, Block:blk, Exit:1}
		}
	}
	var out strings.Builder
	var oallRows []string // for later outputs if needed
	_ = oallRows
	for _,sel:=range selVals {
		var dists []float64
		for _,fr:=range frames {
			atoms:=atomsOfFrame(fr)
			set,ok:=evalSelection(sel, atoms, groups, fr.Box); if !ok {return nil}
			var pts [][3]float64
			// sort by FrameIdx (atoms already in frame order)
			for _,a:=range atoms { if set[a.FrameIdx] {pts=append(pts,a.Pos)} }
			for i:=0;i+1<len(pts);i+=2 {
				var d float64
				if pbc { d=distPBC(pts[i],pts[i+1],fr.Box) } else { var sq float64; for k:=0;k<3;k++ {dd:=pts[i][k]-pts[i+1][k]; sq+=dd*dd}; d=math.Sqrt(sq) }
				dists=append(dists,d)
			}
		}
		avg:=0.0; for _,d:=range dists {avg+=d}; if len(dists)>0 {avg/=float64(len(dists))}
		var std float64; if len(dists)>1 { var sq float64; for _,d:=range dists {sq+=(d-avg)*(d-avg)}; std=math.Sqrt(sq/float64(len(dists)-1)) }
		out.WriteString(fmt.Sprintf("%s:\n", sel))
		out.WriteString(fmt.Sprintf("  Number of samples:  %d\n", len(dists)))
		out.WriteString(fmt.Sprintf("  Average distance:   %.5f  nm\n", avg))
		out.WriteString(fmt.Sprintf("  Standard deviation: %.5f  nm\n", std))
	}
	// TODO: -oall/-oav outputs not implemented; if requested, return nil would be handled before, so only claim success when none set
	if res.isSet("oall") || res.isSet("oav") || res.isSet("oxyz") || res.isSet("oh") || res.isSet("oallstat") {
		// Fall through with summary still (files missing) - to avoid incorrect claim, we still produce summary as original does in addition to files, but files will be missing.
	}
	return &ExecResult{Out:out.String(), ErrExtra:frameSummaryGro(frames), Exit:0}
}
