func handlePairdistTool(res *ParseResult, display string) *ExecResult {
	if res.isSet("s") { return nil }
	fname:=getFileOpt(res,"pairdist","f"); if fileExtOf(fname)!=".gro" {return nil}
	if getEnumOpt(res,"pairdist","refgrouping")!="all" || getEnumOpt(res,"pairdist","selgrouping")!="all" {return nil}
	typ:=getEnumOpt(res,"pairdist","type")
	refVals:=splitSelections(res.values("ref")); selVals:=splitSelections(res.values("sel"))
	if len(refVals)==0 || len(selVals)==0 {return nil}
	for _,s:=range append(append([]string{},refVals...), selVals...) { if selectionRequiresTopology(s) { return &ExecResult{Block:initTopologyError(display), Exit:1} } }
	frames,_,err:=parseGroFile(fname); if err!=nil {return nil}
	var groups []NdxGroup
	if res.isSet("n") { groups,_=parseNdxFile(getFileOpt(res,"pairdist","n")) }
	cutoff:=getFloat(res,"pairdist","cutoff")
	oname:=getFileOpt(res,"pairdist","o")
	var file strings.Builder; xv:=getEnumOpt(res,"pairdist","xvg")
	if xv!="none" {
		file.WriteString(xvgFileHeader(display, xv))
		tit:="Minimum distance"; if typ=="max" {tit="Maximum distance"} else if typ=="pair" {tit="Pair distance"}
		file.WriteString(fmt.Sprintf("@    title \"%s\"\n", tit))
		file.WriteString("@    xaxis  label \"Time (ps)\"\n")
		file.WriteString("@    yaxis  label \"Distance (nm)\"\n")
		if xv=="xmgr" { file.WriteString("@TYPE nxy\n") } else { file.WriteString("@TYPE xy\n") }
		file.WriteString(xvgViewLegend(display, selVals))
	}
	for _,fr:=range frames {
		atoms:=atomsOfFrame(fr)
		refSet,ok:=evalSelection(refVals[0], atoms, groups, fr.Box); if !ok {return nil}
		var refPts [][3]float64; var refIdx []int; for _,a:=range atoms { if refSet[a.FrameIdx] {refPts=append(refPts,a.Pos); refIdx=append(refIdx,a.FrameIdx)} }
		file.WriteString(fmt.Sprintf("%11.3f", 0.0))
		for _,sv:=range selVals {
			selSet,ok:=evalSelection(sv, atoms, groups, fr.Box); if !ok {return nil}
			var selPts [][3]float64; var selIdx []int; for _,a:=range atoms { if selSet[a.FrameIdx] {selPts=append(selPts,a.Pos); selIdx=append(selIdx,a.FrameIdx)} }
			best:=-1.0
			for ri,rp:=range refPts { for sj,sp:=range selPts { if refIdx[ri]==selIdx[sj] {continue}; d:=distPBC(rp,sp,fr.Box); if cutoff>0 && d>cutoff {continue}; if best<0 || (typ=="max" && d>best) || (typ!="max" && d<best) {best=d} } }
			if best<0 {best=0}
			file.WriteString(fmt.Sprintf("    %.3f", best))
		}
		file.WriteString("\n")
	}
	backupMsgs:=""; if msg,blk:=writeOutput(oname, file.String(), res.backupEnabled(), display); blk!=nil {return &ExecResult{Block:blk,Exit:1}} else {backupMsgs=msg}
	return &ExecResult{ErrExtra:frameSummaryGro(frames)+backupMsgs, Exit:0}
}
