func handleMSDTool(res *ParseResult, display string) *ExecResult {
	if res.isSet("s") { return nil }
	if res.isSet("mol") { return nil }
	if getEnumOpt(res,"msd","type")!="unused" && getEnumOpt(res,"msd","type")!="" { /* still handle below for x/y/z */ }
	fname:=getFileOpt(res,"msd","f"); if fileExtOf(fname)!=".gro" {return nil}
	selVals:=splitSelections(res.values("sel")); if len(selVals)!=1 {return nil}
	sel:=selVals[0]
	if selectionRequiresTopology(sel) { return &ExecResult{Block:initTopologyError(display), Exit:1} }
	frames,_,err:=parseGroFile(fname); if err!=nil {return nil}
	if len(frames)==1 {
		return &ExecResult{ErrExtra:frameSummaryGro(frames), Exit:139, SuppressFinal:true, Crash:true}
	}
	if len(frames)==0 {return nil}
	// time step checks at second frame
	dtFrame:=frames[1].Time-frames[0].Time
	if dtFrame < 0.001 {
		var pre strings.Builder
		pre.WriteString(fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n", frames[0].Title, frames[0].NAtoms))
		pre.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", 0, frames[0].Time))
		pre.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", 1, frames[1].Time))
		blk:=&ErrorBlock{Program:display, Source:"src/gromacs/trajectoryanalysis/modules/msd.cpp", Line:676, Func:"virtual void gmx::analysismodules::Msd::analyzeFrame(int, const t_trxframe&, t_pbc*, gmx::TrajectoryAnalysisModuleData*)", Heading:"Inconsistency in user input:", Body:"Time step is too small for accurate MSD calculations, must be at least 1 fs.\n"}
		return &ExecResult{ErrExtra:pre.String(), Block:blk, Exit:1}
	}
	trestart:=getFloat(res,"msd","trestart")
	if dtFrame>0 {
		q:=trestart/dtFrame
		if math.Abs(q-math.Round(q))>1e-4 {
			var pre strings.Builder
			pre.WriteString(fmt.Sprintf("Reading frames from gro file '%s', %d atoms.\n", frames[0].Title, frames[0].NAtoms))
			pre.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", 0, frames[0].Time))
			pre.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", 1, frames[1].Time))
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/trajectoryanalysis/modules/msd.cpp", Line:699, Func:"virtual void gmx::analysismodules::Msd::analyzeFrame(int, const t_trxframe&, t_pbc*, gmx::TrajectoryAnalysisModuleData*)", Heading:"Inconsistency in user input:", Body:"-trestart (default 10 ps) must be divisible by -dt for useful results.\n"}
			// Message body in original does not mention actual values; keep as observed in generic case.
			if trestart!=10 { blk.Body="-trestart must be divisible by -dt for useful results.\n" }
			return &ExecResult{ErrExtra:pre.String(), Block:blk, Exit:1}
		}
	}
	var groups []NdxGroup
	if res.isSet("n") { groups,_=parseNdxFile(getFileOpt(res,"msd","n")) }
	atoms0:=atomsOfFrame(frames[0])
	set0,ok:=evalSelection(sel, atoms0, groups, frames[0].Box); if !ok {return nil}
	var atomIndices []int // FrameIdx in first frame order
	for _,a:=range atoms0 { if set0[a.FrameIdx] {atomIndices=append(atomIndices,a.FrameIdx)} }
	if len(atomIndices)==0 {return nil}
	// unwrapped positions per atom per frame
	// positions[frame][atomPositionInList]
	nAtomsSel:=len(atomIndices)
	positions:=make([][][3]float64, len(frames))
	for fi,fr:=range frames {
		atoms:=atomsOfFrame(fr)
		// map FrameIdx->pos
		posByIdx:=map[int][3]float64{}; for _,a:=range atoms {posByIdx[a.FrameIdx]=a.Pos}
		row:=make([][3]float64, nAtomsSel)
		for ai,idx:=range atomIndices { row[ai]=posByIdx[idx] }
		if fi==0 { positions[fi]=row } else {
			prevWrapped:=make([][3]float64, nAtomsSel)
			// recreate wrapped positions of previous frame
			patoms:=atomsOfFrame(frames[fi-1]); pByIdx:=map[int][3]float64{}; for _,a:=range patoms {pByIdx[a.FrameIdx]=a.Pos}
			for ai,idx:=range atomIndices { prevWrapped[ai]=pByIdx[idx] }
			out:=make([][3]float64, nAtomsSel)
			for ai:=range row {
				for k:=0;k<3;k++ {
					d:=row[ai][k]-prevWrapped[ai][k]
					if len(fr.Box)>=3 && fr.Box[k]>0 { d-=math.Round(d/fr.Box[k])*fr.Box[k] }
					out[ai][k]=positions[fi-1][ai][k]+d
				}
			}
			positions[fi]=out
		}
	}
	maxtauOpt:=getFloat(res,"msd","maxtau")
	maxLag:=len(frames)-1
	if maxtauOpt < 1e307 {
		if dtFrame>0 { if ml:=int(maxtauOpt/dtFrame); ml<maxLag {maxLag=ml} }
	}
	typeAxis:=getEnumOpt(res,"msd","type")
	ndim:=3; axis:=-1
	if typeAxis=="x" {axis=0; ndim=1} else if typeAxis=="y" {axis=1; ndim=1} else if typeAxis=="z" {axis=2; ndim=1}
	originStep:=1
	if dtFrame>0 && trestart>0 { originStep=int(math.Round(trestart/dtFrame)); if originStep<=0 {originStep=1} }
	var taus []float64; var msds []float64
	for lag:=0; lag<=maxLag; lag++ {
		var sum float64; var count int
		for origin:=0; origin+lag<len(frames); origin+=originStep {
			for ai:=0;ai<nAtomsSel;ai++ {
				var sq float64
				if axis>=0 { d:=positions[origin+lag][ai][axis]-positions[origin][ai][axis]; sq=d*d } else { for k:=0;k<3;k++ {d:=positions[origin+lag][ai][k]-positions[origin][ai][k]; sq+=d*d} }
				sum+=sq; count++
			}
