			pre.WriteString(fmt.Sprintf("\rReading frame %7d time %8.3f   ", 1, frames[1].Time))
			blk:=&ErrorBlock{Program:display, Source:"src/gromacs/trajectoryanalysis/modules/msd.cpp", Line:699, Func:"virtual void gmx::analysismodules::Msd::analyzeFrame(int, const t_trxframe&, t_pbc*, gmx::TrajectoryAnalysisModuleData*)", Heading:"Inconsistency in user input:", Body:"-trestart (default 10 ps) must be divisible by -dt for useful results.\n"}
			// Message body in original does not mention actual values; keep as observed in generic case.
			if trestart!=10 { blk.Body="-trestart must be divisible by -dt for useful results.\n" }
			return &ExecResult{ErrExtra:pre.String(), Block:blk, Exit:1}
		}
	}
	var groups []NdxGroup
	if res.isSet("n") { groups,_=parseNdxFile(getFileOpt(res,"msd","n")) }
	atoms0:=atomsOfFrame(frames[0])
	set0,ok:=evalSelection(sel, atoms0, groups, frames[0].Box); if !ok {return nil}
	var atomIndices []int // FrameIdx in first frame order
