		var num,den float64; for i:=range ptsX {num+=(ptsX[i]-mx)*(ptsY[i]-my); den+=(ptsX[i]-mx)*(ptsX[i]-mx)}
		if den==0 {return 0}; return num/den
	}
	slope:=fit(begin,end)
	conv:=1000.0/float64(2*ndim)
	D:=slope*conv
	mid:=(begin+end)/2
	D1:=fit(begin,mid)*conv; D2:=fit(mid,end)*conv
	ferr:=math.Abs(D2-D1)
	oname:=getFileOpt(res,"msd","o")
	var file strings.Builder; xv:=getEnumOpt(res,"msd","xvg")
	if xv!="none" {
		file.WriteString(xvgFileHeader(display, xv))
		file.WriteString("@    title \"Mean Squared Displacement\"\n")
		file.WriteString("@    xaxis  label \"tau (ps)\"\n")
		file.WriteString("@    yaxis  label \"MSD (nm\\S2\\N)\"\n")
		if xv=="xmgr" { file.WriteString("@TYPE nxy\n") } else { file.WriteString("@TYPE xy\n") }
		legends:=[]string{fmt.Sprintf("D[%10s] = %.4f (+/- %.2f) (1e-5 cm^2/s)", sel, D, ferr)}
		file.WriteString(xvgViewLegend(display, legends))
	}
	for i,tau:=range taus { file.WriteString(fmt.Sprintf("%11.3f %s\n", tau, padField(formatG(msds[i]),10))) }
	backupMsgs:=""; if msg,blk:=writeOutput(oname, file.String(), res.backupEnabled(), display); blk!=nil {return &ExecResult{Block:blk,Exit:1}} else {backupMsgs=msg}
